(window.STORIES=window.STORIES||[]).push(...[{"n": 24, "l": "الجزء ٣٢ | موسي ٧ | بين موسي........ وبني اسرائيل ٢ | والجزء ٣٣ | موسي ٨..... وبقرة بني إسرائيل", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الثانية_والثلاثون\n#قصة_موسى_الجزء_السابع\n#بين_موسى_وبني_إسرائيل(٢)\n#قارون\nوقفنا المرة إللي فاتت عند السبعين رجل إللي قالوا لموسى عليه السلام مش هنؤمن غير لما نشوف ربنا بعنينا،\nفربنا عاقبهم بإنه أرسل عليهم صاعقة يعني نار شديدة من السماء أو رجْفة على خلاف في التفاسير، \nلكن إللي يهمنا إنها أمر من  شدته صُعِقُوا وماتوا!\nوبعدها ربنا أحياهم مرة تانية!\n\"فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنتُمْ تَنظُرُون ۩ ثُمَّ بَعَثْنَاكُم مِّن بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ \"\nلإنهم لما ماتوا موسى عليه السلام خاف.. هيرجع يقول إيه لبني إسرائيل\nيقول لهم خرجت بسبعين واحد منهم وكلهم ماتوا ورجعت من غيرهم؟! \nمش هيصدقوه طبعا لإنهم بعقول وقلوب زي ما انتم شوفتوا كده\nوهتحصل فتنة جامدة ساعتها.. فموسى عليه السلام دعا ربنا إنه يُحييهم تاني: \n\"قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّايَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا\"\nيعني كإن موسى عليه السلام بيقول:\nيا رب انت لم تهلكنا قبل كده في يوم المجزرة إللي حصلت، مع إن الهلاك ساعتها كان قريب مننا جدا،\nلكن انت برحمتك عصمتنا منه، أفتهلكنا الآن بما فعل السفهاء منا\nحاشاك يارب إنك تعمل فينا كده، فيارب زي ما عصمتنا من الهلاك يوم المقتلة، اعصمنا اليوم ولا تُهلكنا بما فعل السفهاء منا\nفربنا استجاب لموسى وأحياهم مرة تانية واحد ورا التاني ،  وبقوا شايفين بعض إزاي ربنا بيُحيي الموتى،\nودي آية ومعجزة جديدة تُضاف للآيات المُبهرة إللي شافوها وبتدل على إن محدش فعلا يستحق العبادة غير ربنا الخالق عز وجل\n \nورجعوا كلهم مع موسى عليه السلام لبني إسرائيل،\nبدأ موسى عليه السلام في تعليم بني إسرائيل التوراة من الألواح، فأول حاجة قال لهم إنهم لازم يقبلوا كل اللي في التوراة وينفذوا إللي فيها،\n\"وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍۢ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍۢ فَخُذْهَا بِقُوَّةٍۢ وَأْمُرْ قَوْمَكَ يَأْخُذُواْ بِأَحْسَنِهَا\"\nفقالوا: احنا هنشوف إللي فيها الأول، فلو لقينا الأوامر والنواهي سهلة نعملها هنعملها\nفموسى عليه السلام قال لهم: لأ طبعا، لازم تقبلوها كلها، ده دين\n☆وده والله زي حال ناس كتير اليومين دول\n نيجي نقول لهم الدين بيقول كذا وبيقول كذا.. \nيقوموا ياخدوا منه إللي يوافق مزاجهم وسهل إنهم يعملوه، ولو الموضوع صعب ومحتاج مجاهدة تلاقيهم يسيبوه، وياريتهم يسكتوا ويدعوا ربنا مثلا إنه في يوم من الأيام ربنا يهديهم ويعملوا الصح ويبعدوا عن الغلط\n لأ، ده تلاقيهم راضيين ومكتفيِين باللي خلاص نقّوه من الدين\nوعشان يبقوا في السليم بيدوروا على كلام لشيوخ الله أعلم بيهم عشان ياخدوا فتوى منه باللي همّ عايزينه..\nعلى منهج الشيخ فانوس إللي بيريّح النفوس\nوالمثل بيقول حطها في رقبة عالم واطلع سالم\nوللأسف مش قادرين يفهموا إن لو مسألة فيها خلاف بين العلماء، \nده مش معناه إننا نختار براحتنا و هَوَانا بين أقوال العلماء،\nلأ طبعا الإنسان لازم ياخد بالأحوط،\nوالمطلوب من المسلم لما يلاقي في خلاف إنه يتتبع مراد الله ويدور معاه حيث دار،\nيعني يشوف كده هو إيه إللي ربنا يحبه ويريده ويرضاه ويقوم منفذه\nفصاحب القلب السليم بيخرج من الخلاف وياخد بالأحوط لدينه ويبعد عن الشبهة،\nوالدليل على كلامنا هو قول رسول الله ﷺ:\nإِنَّ الْحَلَالَ بَيِّنٌ، والْحَرَامَ بَيِّنٌ، وبَيْنَهُمَا مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ،\nفَمَنِ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ، وعِرْضِهِ، ومَنْ وقَعَ فِي الشُّبُهَاتِ وقَعَ فِي الْحَرَامِ،\nكَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى، يُوشِكُ أَنْ يَقَعَ فِيهِ، أَلَا وإِنَّ لِكُلِّ مَلِكٍ حِمًى، \nأَلَا وإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وهِيَ الْقَلْبُ\"\nده غير إن لما حد يكون عايز فتوى شرعية لااازم يدور على العالم الثقة الأمين إللي بيتقي الله في الفتوى ومش بيتساهل فيها\nهو احنا مش لما بنكون عايزين نكشف على المخ مثلا مش بندوّر على أحسن الأطباء المتخصصين في المخ عشان نعالج أجسادنا إللي هتفنى في يوم من الأيام؟!\nطيب ماهو الدين أَوْلى وأهم إننا ندور على أفضل العلماء وأتقاهم لله عشان ناخد عنهم ديننا لأن هو ده إللي هنتسأل عنه في القبر \nبني إسرائيل لما قعدوا يراجعوا موسى عليه السلام ده آه هناخده، وده لأ  مش هناخده..واحنا مش هنقدر و...و... \nربنا أمر الملائكة إنهم يرفعوا عليهم الجبل كأنه غمامة على رؤوسهم ...متخيلين الجبل العملاق\n اترفع لفوق وهمّ تحته\n\"وَإِذ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَأَنَّهُ ظُلَّةٌ وَظَنُّواْ أَنَّهُ وَاقِعٌ بِهِمْ خُذُواْ مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُواْ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ\"\nفموسى عليه السلام قال لهم لو مقبلتوش أوامر ربنا كلها على بعضها بدون تفريق في الطاعة، الجبل ده هيقع عليكم.. \nفقبلوا على مَضَض طبعا وسجدوا وقعدوا يبصوا بنص وشهم على الجبل وهم ساجدين\nزي اللي بيضرب بعينه كده في الخفاء\nودي كمان تُعتبر آية جديدة من الآيات إللي ربنا ورّاها لبني إسرائيل عشان يُظهر لهم ألوهيته سبحانه وإن هو المستحق للعبادة، بس ياريت بنو إسرائيل يعتبروا بالآيات \nطيب.. دلوقتي بقى عندنا المنهج لكن فين البلد إللي هيقعدوا ويستقروا فيها\nفاكرين لما قلنا إن يعقوب عليه السلام بنى المسجد الأقصى في القدس وإنه كان ثاني بيت لله في الأرض، \nوكان يعقوب عليه السلام بيسكن في منطقة القدس وبعدين يوسف عليه السلام جابهم مصر في نهاية قصة يوسف\nخلال الزمن ده القدس ومحيط المسجد الأقصى سكن فيهم ناس تانيين وأخدوا الأرض لنفسهم من سكانها الأصليين، وهي أصلا بتاعة نسل يعقوب عليه السلام، \nفربنا أمر موسى عليه السلام إنه ياخد بني إسرائيل ويرجع تاني للقدس أو الأرض المقدسة ويخرّجوا الناس الموجودين هناك عشان يستعيدوا أرضهم ويعيشوا هناك،\n\"يَا قَوْمِ ادْخُلُوا الْأَرْضَ الْمُقَدَّسَةَ الَّتِي كَتَبَ اللَّهُ لَكُمْ\"\nفلما وصلوا قريب من القدس، أرسل موسى عليه السلام اثنا عشر رجلا من بني إسرائيل عشان يدخلوا القدس ويشوفوا الأحوال هناك إيه، زي فرقة استطلاع كده،\nدخل الاثنا عشر رجلا المدينة وشافوا أحوالها والناس إللي فيها ورجعوا لموسى عليه السلام، وقالوا له :\nالأرض إللي احنا روحناها بتطلع لبن وعسل.. يعني مليانة بالخيرات،\n لكن المدينة متحصنة جدا، والناس إللي ساكنين هناك أجسامهم ضخمة وعندهم قوة عظيمة\nفبدأ كل واحد من الاثنا عشر رجل ينهى قومه عن القتال مع موسى عليه السلام ويخوّفهم، \nما عدا رجلين اثنين فقط، همّ بس إللي نصحوهم بإنهم يسمعوا كلام موسى عليه السلام ويقاتلوا معاه.\nلكن بني إسرائيل رفضوا كلام الرجلين وعصوا كلام موسى وقعدوا يقولوا:\nده فيها قوم جبارين واحنا مش هندخلها غير لما القوم الجبارين دول يخرجوا منها\n\"قَالُوا يَا مُوسَىٰ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا مِنْهَا فَإِن يَخْرُجُوا مِنْهَا فَإِنَّا دَاخِلُونَ\"\nربنا أوحى لموسى عليه السلام إنه يصمم عل  قومه إنهم يجاهدوا معاه عشان يستعيدوا أرضهم ويقيموا دولتهم،\nلكن بني إسرائيل ولا همّ هنا\n☆وخدوا بالكم إن القتال أو الجهاد هنا فرض على بني إسرائيل لأن ده جهاد دفع\n \nواحنا عندنا نوعين من الجهاد:\nجهاد الدّفع وجهاد الطلب،\n◇جهاد الدفع هو إني أدافع عن أي حد يعتدي عليَّ أو على أرضي، وده واجب على الجميع،\n◇أما جهاد الطلب فده بيكون إن الجيش يروح يفتح بلد تانية غير مسلمة عشان ينشر الإسلام، \nوجهاد الدفع كان أوله في عهد موسى عليه السلام، \nوأمة الإسلام جمعت بين جهاد الدفع وجهاد الطلب، ودي خاصية لأمة الإسلام لم تكن لأي أمة من الأمم السابقة\n \nممكن يكون في ملوك أفراد يقوموا بجهاد الطلب لنشر الدين زي سليمان عليه السلام كده زي ما هنشوف،\nلكن أول أمة من بدايتها لحد نهايتها مأمورة بجهاد الطلب هي أمة الإسلام\n◇طيب مش ربنا قال لا إكراه في الدين؟ ليه بقى المسلمين يروحوا بلاد تانية عشان يفتحوها\nشوفوا،\nالإسلام هو الرسالة الخاتمة، وربنا خلق البشر عشان يعبدوه، فاحنا كمسلمين لازم نوصل رسالة الإسلام لكل إنسان على وجْه الأرض،\nوطبعا الشعوب إللي متعرفش الإسلام ليها حُكّام بيستفيدوا من عبادة غير الله، وبيحكموا بالقوانين إللي فيها مصلحتهم الشخصية،\nفلما ييجي دين هو إللي يحكم ويُقلل نفوذ الحكام دي طبعا هيحاربوه، زي ما حصل مع فرعون كده،\nفلازم يكون في جيش يحمي الدعاة إلى الإسلام،\nوخصوصا إن الجيوش الإسلامية مش بتحارب الشعوب، همّ بيروحوا البلد ويعرضوا عليهم الإسلام، لو  قِبلوا يبقى خلاص ده إللي احنا عايزينه،\nلكن لو مقبلوش بالإسلام يبقى يدفعوا الجزية في مُقابل إن المسلمين لا يقاتلوهم ويدافعوا عنهم ضد أي عدو بس هيُحكموهم بالشريعة الإسلامية مع بقاءهم على دينهم عادي، طب لو مرضيوش برده\nيبقى القتال، نتبارز ونشوف مين الأقوى والأقوى هو إللي كلمته هتمشي\nوكل دي خطوات عشان رسالة الإسلام توصل لكل الناس بالذات إللي بيبقوا حُكَّامهم مانعين الإسلام بالقوة عن بلادهم، فالإسلام لازم يوصل لهم بالقوة لإن ده حقهم إللي حكامهم حارمينهم منه،\nوالناس نفسها بعد كده ليهم الإختيار...يؤمنوا أو يكفُروا\nيعني الغاية من جهاد الطلب مش القتل والتخريب والاستعباد زي ما التتار والحملات الصليبية عملت في بلاد المسلمين ولّا زي ما بيتهموا الإسلام بده ظلما وعدوانا \nفدلوقتي بنو إسرائيل مفروض عليهم جهاد الدفع، مطلوب منهم يستردوا أرضهم وحقهم وهمّ رافضين ينفذوا أوامر ربنا..\nموسى عليه السلام حاول يقنعهم إنهم يقاتلوا، وهمّ أبدا مش راضيين\nالرجلين الصالحين يقولوا لهم يا جماعة خدوا بالأسباب واتوكلوا على الله وأول ما هتدخلوا ربنا هينصركم ماهو سبحانه إللي بإيده كل حاجة، برده مفيش فايدة\nوكرروا رفضهم التام لدخول الأرض المقدسة، \nوقالوا لموسى وش كده: إحنا مش هندخلها أبدا مادام القوم الجبارين دول فيها، إحنا مش هنقدر نقاتلهم\nوراحوا قايلين كلمة كارثية\nقالوا:\nيا موسى لو الموضوع مهم أوي كده بالنسبة لك روح إنت وربك قاتلوا الناس الجبارة دي وإحنا هنا مستنييكم\n\"قَالُواْ يَا مُوسَى إِنَّا لَن نَّدْخُلَهَا أَبَدًا مَّا دَامُواْ فِيهَا فَاذْهَبْ أَنتَ وَرَبُّكَ فَقَاتِلا إِنَّا هَاهُنَا قَاعِدُونَ\"\nفلما موسى عليه السلام شاف عناد وفسق بني إسرائيل وتجرؤهم على جناب الله عز وجل، دعا ربنا:\n\"قَالَ رَبِّ إِنِّي لا أَمْلِكُ إِلاَّ نَفْسِي وَأَخِي فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ\"\nيعني يارب أنا مليش سلطان عليهم ولا أقدر على حد غير على نفسي أنا وأخويا، \nفاحكم بيني وبين بني إسرائيل الفاسقين بحكمك، بالعقوبة إللي انت ترى إنهم يستحقوها\nفربنا قال:\n\" قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِي الأَرْضِ\" \nيعني العقوبة هتكون إن الأرض المقدسة تبقى مُحَرَّمة عليهم، مش هيدخلوها حتى لو ندموا وحبوا يدخلوها، \nوكمان هيقعدوا تايهين في الصحراء أربعين سنة حيارى لا يهتدون\n \nوالسبب في إن المدة أربعين سنة بالذات عشان يكون الجيل إللي قلبه قاسي زي الحجر ده اختفى، \nو يكون جه من بعده جيل جديد محضرش الذل والخضوع والاستبداد إللي عاشه آباؤهم عند فرعون فيكون أقرب للفطرة السليمة إللي ترفض الذل والعبودية لغير الله \nبدأ زمن التيه...وحصلت فيه أحداث كتير مهمة منها وآيات جديدة لعل منهم مَن يعتبر.. منها: إن ربنا نزل عليهم المّنَّ والسلوى.. \nعايشين في صحراء.. في الحر والشمس والتوهان مش عارفين طريق للخروج.. \nقالوا لموسى عليه السلام إنهم جعانين والدنيا حر وخلاص مش قادرين،\nفدعا موسى ربنا فأرسل الله لهم السحاب يغطي عليهم من حر الشمس، وأنزل عليهم المنّ والسلوى..\nوالمنّ هو شيء يشبه الصّمغ في الملمس، وطعمه أحلى من العسل، بينزل من الأشجار يتم خلطه بالماء ويتشرب، والسلوى دة طائر زي طائر السمان كده،\nفكان ربنا موفر لهم كل حاجة، يعني أكلين شاربين نايمين ومتظللين و مش تعبانين في أي حاجة، وكانوا قبل كده مُستعبدين ومقهورين ومكنوش بيتكلموا،\nمش يشكروا النعمة والعافية بقى \nلااااأ ...ده قالوا لموسى: يا موسى احنا مش بناكل غير صنف واحد بس واحنا مش مستحملين بصراحة\n☆أيوة يعني عايزين إيه\nاطلب من ربك إنه يطلع لنا من الأرض البصل والعدس والقمح\n\"وَإِذْ قُلْتُمْ يَا مُوسَى لَن نَّصْبِرَ عَلَىَ طَعَامٍ وَاحِدٍ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنبِتُ الأَرْضُ مِن بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا\"\nفكإن لسان حال موسى عليه السلام بيقول:\nيعني بتقولوا ادعوا لنا ربك ..أنا فكرت انكم هتطلبوا مائدة من السماء مثلا أو حاجة كده عظيمة بما إنكم طالبين إني أشفع لكم عند ربنا في استجابة الدعاء\nبقى عاوزين تسيبوا المن والسلوى الأطعمة الشهية النادرة بالنسبة لكم دي عشان تاكلوا بصل وعدس إللي كل الناس بتاكله عادي\n\"أَتَسْتَبْدِلُونَ الذي هُوَ أدنى بالذي هُوَ خَيْرٌ\"\n☆لو تلاحظوا كده معايا كل شوية بنو إسرائيل ينادوا موسى عليه السلام باسمه كده من غير ألقاب وتوقير،\nمفيش يا رسول الله مثلا؟ أو يا نبي الله؟ أو يا سيدنا موسى؟\nسوء أدب واضح مع موسى عليه السلام مع كل إللي عمله عشانهم، \nوحتى مفيش في كلامهم أي اعتراف بالجميل إللي عمله معاهم وإنه جاء وأخرجهم من الاستعباد والظلم\nلأ وكمان كل شوية \"ربك\" ربك\"، ادع لنا ربك... اذهب أنت وربك..إيه ربك دي\nسوء أدب كمان مع ربنا عز وجل،  وكأنهم كل شوية بيسجلوا مثلا إن احنا مش معترفين إنه ربنا احنا كمان ده ربك انت بس لحد ما نقرر \nوشوية يؤمنوا وشوية يكفروا وينتكسوا، وحتى وهمّ مؤمنين بيكونوا مذبذبين ومتشككين،\nوكل ده وربنا حليم عليهم وموسى عليه السلام صابر عليهم وعلى تأديبهم وتربيتهم على الإيمان والمكارم،\nواستمر موسى عليه السلام في معاناته مع بني إسرائيل\nكان في قوم موسى عليه السلام واحد اسمه قارون.. شخص مالوش أي مكانة ولا نسب ولا أي حاجة،\nكل ما في الموضوع إن ربنا أغناه وعنده فلوس كتير...بكل بساطة عارفين اللئيم إللي بيغتني بعد فقر بيكون عامل إزاي؟!  \nأهه ده كان قارون\nوربنا أغناه مش أي غنى ...ده كانت مفاتيح الخزائن بتاعته ميشيلهاش إلا مجموعة من الرجال الأقوياء وبالعافية كمان \nفتقدروا تقولوا إن أموال أغنياء العالم كلهم دلوقتي كانت تعتبر الفكة إللي كانت في جيب قارون ساعتها\nفلكم أن تتخيلوا كان غني أد إيه\n\"إنَّ قَارُونَ كَانَ مِن قَوْمِ مُوسَى فَبَغَى عَلَيْهِمْ وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ\"\nفالناصحين كانوا بينصحوه بإنه ميفرحش وميتغرِّش في نفسه يعني عشان معاه الأموال دي كلها،\n\"إِذْ قَالَ لَهُ قَوْمُهُ لَا تَفْرَحْ إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ\"\nوإنه يخلّي همته إنه يستعمل الأموال دي في رضا ربنا ويكون همه الآخرة،\nفمهما عشت يا قارون فكل ده هيفنى ومش هيكون عندك في رصيدك في الآخرة غير إللي إنت بذلته في حياتك لله وفي مرضاته\n\"وَابْتَغِ فِيمَا آتَاكَ اللَّهُ الدَّارَ الْآخِرَةَ ۖ وَلَا تَنسَ نَصِيبَكَ مِنَ الدُّنْيَا\"\nوزي ما ربنا أحسن إليك وأكرمك بإنه أعطاك الأموال دي كلها فأحسِن للناس المحتاجة ولا تُهِنهم؛ فربنا يعاقبك وياخد منك النعم إللي انت فيها دي\n\"وَأَحْسِن كَمَا أَحْسَنَ اللَّهُ إِلَيْكَ ۖ وَلَا تَبْغِ الْفَسَادَ فِي الْأَرْضِ ۖ إِنَّ اللَّهَ لَا يُحِبُّ الْمُفْسِدِينَ\"\nرد عليهم قال لهم: \nالأموال إللي عندي دي أنا إللي جمعتها بعلمي وشطارتي وربنا أعطاني الأموال دي عشان هو يعلم إني أستحق الأموال دي، ولو هو ما كانش بيحبني مكنش إداني الأموال دي كلها \n\"قَالَ إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلْمٍ عِندِي\"\n☆هو مش فاهم إن ربنا بيعطي الدنيا لمن يحب ومن يكره، لكن الآخرة بس هي إللي ربنا بيعطيها لمن يحب من عباده المؤمنين..\nمش فاهم إن الدنيا لو كانت تساوي عند الله جناح بعوضة مكنش ربنا سقى الكافر فيها شربة مية،\nفما بالنا والكفار عندهم الأموال والسلطان؟\nفالعبرة بالآخرة مش بالدنيا أبدا\nمش فاهم إن الأعمال الصالحة هي إللي بتقرب العبد من ربه مش الأموال ولا الأولاد\nوفي يوم من الأيام اتزين بأبهى زينة، وخرج على قومه في موكب عظيم وحواليه الخدم،\n\"فَخَرَجَ عَلَى قَوْمِهِ فِي زِينَتِهِ\"\nفشافه الناس إللي حب الدنيا متمكن في قلوبهم؛ فتمنوا إنهم يكون عندهم زي اللي عنده وقالوا:\nيا ريت عندنا إللي عند قارون.. ده محظوظ حظ\n\"قَالَ الَّذِينَ يُرِيدُونَ الْحَيَاةَ الدُّنيَا يَا لَيْتَ لَنَا مِثْلَ مَا أُوتِيَ قَارُونُ إِنَّهُ لَذُو حَظٍّ عَظِيمٍ\"\n☆مش بنسمع الكلمة دي من ناس حوالينا لما يشوفوا حد عنده أموال أو مكانة اجتماعية أو شهرة في الباطل ..مش بيقولوا: يا سلام لو كنا مكانهم أو عندنا زيهم\nفهنا أهل العلم العقلاء من بني إسرائيل قالوا لهم يا جماعة دي دنيا وكل ده هيفنى ..الثواب في الآخرة أعظم وأبقى..\n\"وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَيْلَكُمْ ثَوَابُ اللَّهِ خَيْرٌ لِّمَنْ آمَنَ وَعَمِلَ صَالِحًا وَلَا يُلَقَّاهَا إِلَّا الصَّابِرُونَ\"\nوقارون بقى ماشي في زينته متكبر بالمنظر ده، ربنا خسف بيه الأرض\nالأرض انشقت وبلعته هو وكنوزه وأمواله\n\"فَخَسَفْنَا بِهِ وَبِدَارِهِ الْأَرْضَ فَمَا كَانَ لَهُ مِن فِئَةٍ يَنصُرُونَهُ مِن دُونِ اللَّهِ وَمَا كَانَ مِنَ المُنتَصِرِينَ \"\nفلما شاف الناس إللي اتمنوا إنهم يكون عندهم زيه، ندموا وشكروا ربنا إنهم مكنوش في مكانه..\n\"وَأَصْبَحَ الَّذِينَ تَمَنَّوْا مَكَانَهُ بِالْأَمْسِ يَقُولُونَ وَيْكَأَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاء مِنْ عِبَادِهِ وَيَقْدِرُ لَوْلَا أَن مَّنَّ اللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُ لَا يُفْلِحُ الْكَافِرُونَ\"\nوآدي كمان آية جديدة لبني إسرائيل على قدرة الله واستحقاقه للعبودية وعدم عصيانه، وكل شوية ربنا بيوريهم آيات ورا آيات لعلهم يهتدون أو يتقون\nإن شاء الله المرة الجاية نكمل الأحداث إللي حصلت زمن التيه\n#قصص_الأنبياء\n#الحلقة_الثالثة_والثلاثون\n#قصة_موسى_الجزء_الثامن\n#بقرة_بني_إسرائيل\nعرفنا المرة إللي فاتت إن بني إسرائيل دخلوا في التيه، وفي التيه ده حصلت أحداث كثيرة..كان منها قصة قارون إللي قلناها المرة إللي فاتت،\nوالنهاردة هنتكلم عن قصة البقرة\nكان في بني إسرائيل رجل غني مكنش عنده أبناء، لكن كان له قريب، لو الرجل الغني ده مات كان القريب ده هيورثه، فمقدرش يصبر لحد ما الراجل يموت لوحده، فراح قاتله ورماه على الطريق،\nالناس صحيوا الصبح لقوا واحد مقتول على الطريق\nوجه قريبه القاتل ده وقعد يصوّت ويندب عليه قال يعني كإنه اتفاجيء،\nوعلى رأي المثل: يقتل القتيل ويمشي في جنازته \nفبدأ الناس كل واحد فيهم ينفي التهمة عن نفسه ويرمي بيها غيره وحصل نزاع في الأمر..\n\"وَإِذْ قَتَلْتُمْ نَفْسًا فَادَّارَأْتُمْ فِيهَا ۖ وَاللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ\"\nفالقاتل قال لموسى عليه السلام: مفيش حد هيقول لنا مين إللي قتله غيرك يا نبي الله\n☆يعني مش بس قتل، ومش بس بيقتل القتيل ويمشي في جنازته ويمثل على الناس البراءة، \nلأ، ده كمان بكل بجاحة رايح لموسى عليه السلام إللي بيجيله الوحي من ربنا عالم الغيب والشهادة يسأله مين إللي قتل قريبه\nيعني بيحاول يُسبُك الحكاية أكتر على طريقة قال يعني هو بريء لدرجة إنه مصمم ياخد بكل الأسباب لكشف القاتل،\nوده معناه إنهم فعلا عارفين إن موسى عليه السلام نبي لكنهم مستهزئين بيه وقلوبهم فيها شك في الإيمان دايما ومليانة ريبة ومرض\nفبنو إسرائيل قالوا لموسى عليه السلام: صح! مش انت نبي؟! ادعي ربك واسأله مين قتل قتيلنا\nفدعا موسى عليه السلام ربنا عز وجل يكشف القاتل، فربنا أوحى له إنه يؤمر بني إسرائيل إنهم يذبحوا بقرة، فاستهزأوا بيه وبطلبه..\n\"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا بَقَرَةً  قَالُوا أَتَتَّخِذُنَا هُزُوًا\"\nيعني بيقولوا له بقى إحنا بنقولك مين قتل القتيل؟ تقوم إنت تقول لنا اذبحوا بقرة\n \nانت بتهزر \nفموسى عليه السلام قال لهم: \n\"قَالَ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ\"\nيعني هو انتم جربتم عليّ قبل كده كذب على الله عزو وجل أو استهزاء بيكم أو بأي حد من الناس؟ \nأنا بقالي كم سنة عايش معاكم.. هل حصل مني أي حاجة من دي قبل كده\nفقعدوا يجادلوه ويصعّبوا الموضوع أكتر: \nطيب ما تقول مين قتل قتيلنا ؟\n فموسى عليه السلام مزودش معاهم في الكلام أكتر من إنه كرر عليهم الأمر الإلهي \"اذبحوا بقرة\"..\n☆طيب هنا سؤال: اشمعنى بقرة\n...  ليه مش خروف ولا شاة ولا أي حيوان تاني\nالسبب في كده لأنهم عبدوا العجل.. فربنا طول الوقت بيربيهم على ترك عبادة العجل وبيعلمهم إنهم ينزعوا تقديسه تماما من قلوبهم،\nقلوبهم كان متشربة حب عبادة العجل بدرجة كبيرة جدا،\nفلما مرة يحرقوا الإله المزعوم إللي عبدوه وقدسوه قبل كده وكان على شكل عجل ونثروا الرماد بتاعه في الهواء، \nوبعدين مرة تانية يذبحوا بقرة إللي هي برده من نفس الفصيلة فالمفروض إنه يقع في قلوبهم:\nإزاي إله ويُذبح ويهلك\nويقتنعوا بقى إن صفات الإله مختلفة عن إللي بيعبدوه ده\n \nالمفروض يعني، لكن هنقول إيه\nالمهم.. كملوا جدال وعناد مع موسى وأسئلة فارغة : \n\"قَالُواْ ادْعُ لَنَا رَبَّكَ يُبَيِّن لّنَا مَا هِيَ\"\nاسأل ربك البقرة دي عاملة إزاي\n\" قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لاَّ فَارِضٌ وَلاَ بِكْرٌ عَوَانٌ بَيْنَ ذَلِكَ فَافْعَلُواْ مَا تُؤْمَرونَ\"\nيعني ابحثوا عن بقرة متوسطة لا هي كبيرة ولا هي صغيرة، وانجزوا واعملوا إللي ربنا أمركم بيه بسرعة من غير تأجيل\n☆وهنا فيه قاعدة مهمة\nوهي إن لما الأمر يجيلنا من ربنا، يجب التفيذ فورا\nيعني مش لسه هشوف ظروفي تسمح ولاّ لأ! \nولّا هينفع وسهل معايا ولّا لأ، ولّا هيكون معايا حد ولّا هبقى لوحدي،\nالموسيقى حرام يبقى أوقف فورا، الصلاة فرض ربنا أمر بيها؛ يبقى أصلّي حالا، \nالحجاب ميكونش زينة ويكون ساتر للزينة؛ يبقى أقول سمعا وطاعة فورا يارب،\nمش أقعد أدرّج لنفسي الحجاب كل سنة أغطي حتة\nأنفذ أوامر ربنا فورا ، مش أقول لما ربنا يهديني وأقعد أسوّف في الطاعة وأقول \"سوف.. سوف.. سوف...\" \nدول بقى جدال وتضييع وقت مع إن الطلب واضح وربنا سهّل عليهم من البداية بدون شروط!\nفقالوا له تاني : طيب اسأله كده لونها إيه\n \n\"قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا\"!\nفقال لهم:\nلونها أصفر.. بس مش أصفر عادي سهل تلاقوه،\nلأ أصفر فاقع، ويكون شكله حلو مش أصفر يوجع العين ويبقى شكله وحش\n\"قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ النَّاظِرِينَ\"\nبقت العملية أصعب! شدّدوا على أنفسهم فشُدِّدَ عليهم! \nطيب هل سمعوا الكلام بقى وفهموا واعتبروا؟\nإطلاقا\nقالوا لموسى خلّي ربك يا موسى يوضح لنا صفاتها أكثر لإن البقر إللي بالصفات دي كتير برده ومش هنقدر نميز البقرة المطلوبة من بينهم\n\"قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ الْبَقَرَ تَشَابَهَ عَلَيْنَا وَإِنَّا إِن شَاءَ اللَّهُ لَمُهْتَدُونَ\"\nفقال لهم: دي بقرة مُدللة.. متدلعة يعني... لا بتروح حقل تحرث، ولا حتى بتسقي الزرع، ومش بس كده لأ ميكونش فيها أي عيب،\nإللي هو شوفوا بقى هتلاقوها إزاي دي\n\"قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلَا تَسْقِي الْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا \"\n☆وطبعا كل ده نتيجة التشدد زي ما قلنا \n ربنا كان ميسرها عليهم لكن همّ قعدوا يشددوا على نفسهم، \nعارفين زي إيه\nزي الشخص إللي بيسأل سؤال والشيخ يقول له:\n \"افعل ولا حرج\" زي ما قال النبي ﷺ  في الحج والعمرة مثلا،\nفيقوم يلِح على الشيخ:\nطب أنا حطيت مرهم دوا له ريحة نفّاذة بس مهياش الريحة الحلوة بتاعة العطور، هل كده ده عِطر وبلاش أحط الدوا؟ طب أنا الخروف إللي جبته للأُضحية عنده خربوش قُطة صغير في طرف القرون بتاعته مش باين إلا بالعدسة المكبرة، هل ينفع أضحي بيه؟ \nطب أنا ينفع أتيمم بسبب الجرح المفتوح ده بس أنا هتوضى بالمية بردو ومش مهم تحذير الدكتور! .. وهكذا..\nوكان في موقف زي كده حصل في زمن رسول الله ﷺ ، ناس قعدت تسأله عن حاجات هو سكت عنها في الشرع عشان التخفيف على المسلمين،\nولو جاوب عنها هتبقى فرض يُعاقَب تاركه! \nزي ما واحد سأله عن الحج، هل لازم نحج كل عام، فقال لهم: لو قلت نعم لوجبت ولما استطعتم،\nفحذرهم من ده ونزلت الآية: \nيَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ عَفَا اللَّهُ عَنْهَا ۗ وَاللَّهُ غَفُورٌ حَلِيمٌ ۩ قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا بِهَا كَافِرِينَ\"\nبنو إسرائيل بعد ما سمعوا الوصف الأخير قالوا بااااس انت كده جبت الوصف المطلوب زي ما احنا عاوزين\n\"قَالُوا الْآنَ جِئْتَ بِالْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا يَفْعَلُونَ\"\n☆سوء أدب متواصل مع موسى عليه السلام ومع طريقة استقبالهم لأوامر ربنا\nواخدين بالكم من الفرق بين موسى عليه السلام وبينهم؟\nلما ربنا أمر موسى عليه السلام إنه يُلقي عصاه العزيزة عليه وإللي ملوش غنى عنها، عمل إيه؟\nنفّذ وأطاع فورا\nمع إن الطلب يُعتبر ضد المنطق العقلي البشري القاصر،\nيعني لسان حالنا بيقول إيه إللي يخليني أرمي عصايتي إللي بحبها كده من غير استفهام بسيط عن السبب حتى\nضد المنطق النفسي والعقلي بالنسبة لأي حد زي ما ذبح البقرة هنا بالنسبة لبني إسرائل  كان شيء ضد المنطق في إللي طلبوه من موسى.. \nومع ذلك بني إسرائيل لما جالهم الأمر حكّموا العقل والمنطق فكانت النتيجة إنهم اعترضوا على أمر الله واتهموا نبي مُرسل بالاستهزاء بيهم وكإنه جاي يهزر مش جاي برسالة عظيمة وهي الحق من رب العاملين \nولو إنهم سمعوا الكلام على طول بدون نقاش كان الموضوع خلص على طول و انتهى،\nوخصوصا مادام وضَح لهم إن رسالة موسى عليه السلام هي الحق من رب العالمين\nفبدأوا يصعّبوا الأمور على نفسهم، ويسألوا في الأمور الواضحة، فربنا ضيّق عليهم ...\nوكانوا كل ما يسألوا أكثر ربنا يضيق عليهم أكثر، وده يعلمنا إن السؤال فيما لا يفيد مفهوش أي خير، بل ممكن يسوؤنا في النهاية زي ما قلنا.\nالمهم بقى قعدوا يدوّروا على بقرة بالمواصفات دي مش لاقيين نهائي، \nلحااااد ما لقوها عند امرأة عجوز عندها يتامى، فلما عرفت إن بني إسرائيل محتاجين البقرة بشدة، مرضيتش تبيعها إلا بوزنها ذهب\nفرجعوا لموسى عليه السلام وقالوا له الخبر، فقال لهم فضلتوا تشددوا على نفسكم وربنا كان مخفف عنكم، \nخلاص، قُضيَ الأمر، ادوها إللي تطلبه\nففعلا اشتروا البقرة بوزنها ذهب وذبحوا البقرة أخيرا، وأخدوا جزء من البقرة وضربوا بيه القتيل،\nفقام القتيل من موته وقال عن اسم الشخض إللي قتله..إللي هو قريبه ، وبنو إسرائيل مندهشين إزاي الرجل طلع لئيم ومخادع بالشكل ده\nومذهولين من معجزة إحياء الموتى إللي شافوها قدام عنيهم وحصلت بمجرد ضرب القتيل بجزء من حيوان مذبوح\n آيات ورا آيات لبني إسرائيل تدل على صدق ما جاء به موسى وضرورة طاعته.. لكم مين يفهم\nوفي النهاية، أخدوا القاتل وقتلوه قَصاصا للقتيل.\n☆طيب هو ليه ربنا بيحكي لنا القصة دي\nقصة البقرة في الجزء الأول من سورة البقرة، والجزء ده بيحكي عن بني إسرائيل ومشاكلهم مع موسى عليه السلام لما كانوا لسه دولة ناشئة بعد ما خرجوا من مصر.. \nوسورة البقرة من أوائل السور المدنية، يعني نزلت في بداية نشأة الدولة الإسلامية في المدينة وفيها عشرات من التشريعات للمسلمين هتلاقوها من بداية الجزء التاني.. تشريعات في الصلاة ،تشريعات في الحج، تشريعات في الجهاد، تشريعات في الزواج،\nتشريعات في الصيام.. فربنا بيقول للمسلمين ماتعملوش زي بني إسرائيل وتقعدوا تسألوا وتعاندوا وتتباطؤوا في الطاعة..\nمادام انتم خلاص تيقنتم إن ده رسول من عند الله يبقى لما يجيلكم الأمر منه تنفذوه بدون تردد أو شك أو عناد أو جدال،\nقال لكم صوموا ثلاثين يوم تصوموا ...\nقال لكم تصلوا خمس صلوات في اليوم والليلة تصلوا....\nقال لك متبصش على النساء ، متبصش.. \nقال لكِ تلبسي حجاب سابغ ساتر غير ملفت وغير متعطر ومفيهوش زينة ، تلبسي..\nتخيلوا لو المسلمين أخذوا كل تشريع بطريقة بني إسرائيل في الأسئلة؟ يبقى مفيش دولة هتقوم\nهنفضل متكعبلين في الجدالات والتباطؤ والتشدد.. ومش هنفوق للمهام العظيمة إللي محتاجة كل وقتنا وجهدنا وطاقتنا وتفكيرنا،\nده غير إن الجدال والتباطؤ في تنفيذ أوامر الله بيبقى علامة لمرض القلوب والشك في الإيمان،\nوده بيبقى من أكبر أسباب تخلف الأمم المسلمة وتأخر وقوفها على رجليها\nوطبعا كلنا عارفين إن في الوقت الحاضر للأسف ده حاصل، نيجي نقول لحد حكم شرعي صحيح وثابت، يقول إزاي يعني ! \nماهو بالعقل كده المفروض نعمل كذا كذا بدل كذا... مجرد إن عقلهم مش مستوعب الحكمة من الحكم الشرعي الفلاني ، يقوموا يرُدوا حكم ربنا ويتركوا تنفيذه، \nلأ وكمان يقولوا لك : ربنا عرفوه بالعقل! ولا يمكن يرضيه إننا نعمل كذا إللي انت بتقول عليه إنه حكم شرعي ثابت بالقرآن والسنة ده\n انت أكيد فاهم النص غلط.. لازم نعيد فهم النصوص حسب المعطيات العصرية المناسبة لزماننا إلى آخر الحجج والأباطيل إللي من خلالها بيتم هدر نصوص الشريعة حتة حتة،\nمش مثلا يتهموا العقول القاصرة وعلمها محدود وإنها مش فاهمة ويحاولوا يفهموا ويقولوا رب زدني علما\n لأ .. طالما الكلام مش داخل الدماغ يبقى خلاص نرده ونقعد نجادل ونسأل ونتتبع زلات العلماء وناخد إللي على هوانا\n \nالمهم،\nفي يوم من الأيام كان موسى مجتمع مع بني إسرائيل بيكلمهم عن ربنا ويوعظهم، \nلحد ما الناس قلوبها اتأثرت وعيطوا من شدة التأثر بكلامه عليه السلام،\nزي ما بنسمع محاضرة ونتأثر بكلام الشيخ وساعات من شدة التأثر كده عينينا تدمع\nفده كان الحال مع بني إسرائيل في اليوم ده،\nفواحد من بني إسرائيل سأل موسى عليه السلام :\nهل في أحد في الأرض من هو أعلم منك\nفموسى عليه السلام على حسب علمه رد وقال: لأ مفيش.. فربنا عتب عليه إنه لم يُرجِع العلم لله في السؤال الغيبي ده إللي ميعرفش إجابته غير ربنا ويقول الله أعلم،\nوقال له الله عز وجل إن فعلا في عبد صالح مؤمن هو أعلم منك\nفموسى عليه السلام مع إنه نبي مرسل ومن أُولي العزم من الرسل ، إلا إنه قال لربنا إنه عايز يروح يقابل العبد ده وإللي عنده علم مش عنده عليه السلام؛عشان يتعمل منه ويزداد حكمة وبصيرة.\nفربنا استجاب طلبه،  وقال له إن في مكان اسمه \"مجمع البحرين\" هتلاقي العبد الصالح ده موجود هناك عنده.. \nولإن موسى عليه السلام ميعرفش المكان ده، فربنا أمره ياخد معاه سمكة ميتة مملحة عشان متعفنش وأمره إنه ويحطها في جراب《زي شنطة كده》، \nولما يوصل للمكان المحدد هيلاقي السمكة دي رجعت فيها الروح تاني ونزلت المية، وساعتها لما يشوف العلامة دي يبقى هو ده مكان اللقاء.\nأخذ موسى عليه السلام في الرحلة دي غلام من غلمانه اسمه يوشع بن نون، وفهّمه السبب في الرحلة دي: \n\"وَإِذْ قَالَ مُوسَى لِفَتَاهُ لَا أَبْرَحُ حَتَّى أَبْلُغَ مَجْمَعَ الْبَحْرَيْنِ أَوْ أَمْضِيَ حُقُبًا\"\nيعني همشي لحد ما ألاقي مجمع البحرين يا إما هفضل ماشي زمن طويل لحد ما ألاقي العبد الصالح،\nوخرجوا في الرحلة دي، فضلوا ماشيين لحد ما وصلوا عند مجمع البحرين، وهو في وقتنا الحاضر نقطة التقاء خليج العقبة وخليج السويس بجنوب سيناء\nلما وصلوا، موسى عليه السلام نام، في حين إن يوشع بن نون كان صاحي، \nفشاف الجراب بيتحرك ولقى السمكة طلعت منه ونزلت في المية وفضلت واقفة ما بتتحركش!\n\"فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا\"\nسمكة ميتة مملحة فجأة تنط من الجِراب وتتحرك وتسبح في المية كده\nيوشع كان ناوي يحكي لموسى أول ما يصحى، لكن لما صحي موسى عليه السلام، نسي يوشع إنه يقول له إللي حصل،  ومشيوا هم الإتنين وكملوا الطريق،\n\"فَلَمَّا جَاوَزَا قَالَ لِفَتَاهُ آتِنَا غَدَاءنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَذَا نَصَبًا\"\nيعني فجأة موسى عليه السلام وهو ماشي مع فتاه، حس بالتعب والجوع، وهو مكانش حاسس بتعب طول الطريق إللي قبل النوم لكن حس بتعب فجأة،\n فقال لغلامه يوشع هات الغدا بتاعنا احنا تعبنا في السفر الأخير ده ومحتاجين نتقوّى على باقي الطريق، \nهنا افتكر يوشع إللي حصل مع السمكة وحكى لموسى عليه السلام،\n\"قَالَ أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا أَنسَانِيهُ إِلَّا الشَّيْطَانُ أَنْ أَذْكُرَهُ ۚ وَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ عَجَبًا\"\n يعني أنا افتكرت دلوقتي، \nانت لما نمت عند الصخرة حصل كذا كذا ، والشيطان نساني أقولك إزاي السمكة دي فعلا صحيت رغم موتها ونطت في البحر بشكل عجيب! \nفقال له موسى عليه السلام:\n\"قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ ۚ فَارْتَدَّا عَلَىٰ آثَارِهِمَا قَصَصًا\"\nيعني هو ده المكان إللي احنا عايزينه إللي ربنا عز وجل قال لي إن دي علامته، ورجعوا تاني من نفس الطريق متتبعين آثار رجلهم لنفس النقطة\n☆هنا نستفيد نقطة مهمة أوي ، وهي إن طول ما الإنسان بيعمل حاجة لله صح وبصدق ربنا بيهوّن عليه الصعوبات إللي ممكن يواجهها،\nموسى عليه السلام خرج عشان يطلب العلم، فمكنش حاسس بتعب لإن ربنا مخفف عنه لإنه عنده هم أكبر من مجرد الأكل والشرب،\nوهو هم طلب العلم وطلب الحكمة والبصيرة أينما كانت،\nوالعلم بيزود الإيمان واليقين،\nفكل ما كان هم الإنسان عالي وصادق فيه كانت معية ربنا له أكبر وتيسيره لأموره أعظم،\nلكن لما مشي في الطريق الخطأ وبِعِد عن المطلوب منه تِعِب،\nيعني كإن ربنا بيديله له علامة عشان ينتبه\n◇مش بتحصل معانا ساعات؟\n بنبقى ماشيين في طريق الإلتزام وطلب العلم وفجأة نلاقي الدنيا وقفت\nممكن يكون من الأسباب إن احنا ماشين في الطريق الغلط، ويكون ده من لطف ربنا\nيعني مثلا تكون مش عارف تقرأ قرآن وبتغلط في نطق حروفه جدا ومبتعرفش تتوضى صح ولا بتستنجى من النجاسات صح، \nوتقوم رايح شادد حيلك في تعلم مصطلح الحديث وأصول الفقه وتاريخ البلاغة العربية\nهو جميل وعلم نافع جدا وتأسيسي وكل حاجة، لكن انت كده أكيد ماشي غلط من حيث الأولويات والمطلوبات العاجلة الأول،\nلإن الأَولى إنك تتعلم قراءة القرآن الأول نطقا وفهما وفقه العبادات وعلى رأسها الصلاة، عشان هو ده إللي هيصلّح لك صلاتك إللي هتتسأل عنها بين يدي الله عز وجل ولو فرطت في تمام أداءها هتبقى كارثة لأنها أول حاجة العبد بيتسأل عنها يوم القيامة \nفلما تلاقي الدنيا اتسدت في وشك ، فكر كده:\nهل أنا ماشي صح طيب؟ هل ده الطريق إللي هيوصلني لنهاية الطريق إللي أنا عايزه ومخططله؟ \nولا أنا عديت المكان الصحيح ومحتاج أعيد حساباتي وألِف وأرجع ، زي ما حصل مع موسى عليه السلام\nموسى عليه السلام لف ورجع للمكان إللي كانوا فيه لقوا واحد قاعد في الأرض، لما قام الرجل ده الأرض اهتزت، وتحوّل المكان إللي كان واقف فيه لأرض خضراء\nفكان ده العبد الصالح إللي ربنا قال لموسى عليه،\n\"فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَا آتَيْنَاهُ رَحْمَةً مِنْ عِندِنَا وَعَلَّمْنَاهُ مِن لَّدُنَّا عِلْمًا\"\n العبد ده كان اسمه: الخِضْر.. موسى عليه السلام سلم عليه.. فالخضر استغرب من السلام لأن مفيش حد في المنطقة دي بيقول السلام.\n فسأله: انت مين؟ :قال له موسى، فالخضر قال له : موسى بني إسرائيل\nفموسى عليه السلام قال له : نعم، فالخضر استغرب ، موسى بني إسرائيل عايز مني إيه\nفموسى عليه السلام قال له:\nأنا عرفت من ربي إن عندك علم مش عندي، فأنا عايز أتعلم العلم إللي عندك ده، لكن أنا عايز العلم إللي ينفعني ويكون من أسباب الحكمة والرشد \n\"قَالَ لَهُ مُوسَى هَلْ أَتَّبِعُكَ عَلَى أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا \"\nفالخضر قال له إن ربنا أعطاك علم مش عندي وأعطاني علم مش عندك، والعلم إللي عندي انت مش هتصبر عليه ولا هتقدر تستحمله،\n\"قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا ۩ وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِ خُبْرًا\"\nفموسى عليه السلام قال له: إن شاء الله هكون صابر وهسمع كلامك،\n\"قَالَ سَتَجِدُنِي إِن شَاءَ اللَّهُ صَابِرًا وَلَا أَعْصِي لَكَ أَمْرًا\"\n فلما الخضر شاف إصرار موسى عليه السلام وافق إنه يتّبعه لكن بشرط\nقال له: لو هتتبعني متسألنيش عن أي حاجة نهائي إلا لو أنا إللي قلتلك شرحها وتفسيرها \n\"قَالَ فَإِنِ اتَّبَعْتَنِي فَلَا تَسْأَلْنِي عَن شَيْءٍ حَتَّىٰ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا\"\nفموسى عليه السلام وافق، وبدأت رحلة موسى عليه السلام والخضر.\nكان الخضر عايز يعدي الناحية التانية من البحر، فكان فيه سفينة لمساكين بيشتغلوا عليها فلما شافوا الخضر وكانوا عارفينه، مرضيوش ياخدوا منه أي أجرة، وركّبوه هو وموسى عليه السلام في السفينة ببلاش.\n¤ملحوظة:\nالمسكين هو إللي يملك شيء ولكن لسه محتاج تاني، عنده أموال مثلا لكن مش مكفياه، \nأما الفقير فهو إللي معندهوش أي شيء إطلاقا.\nلما ركبوا السفينة نزل الخِضر أسفل السفينة وأخد فأس وخرق لوح من السفينة!، وموسى عليه السلام شايف ومذهول ومستنكر!\n\"فَانطَلَقَا حَتَّىٰ إِذَا رَكِبَا فِي السَّفِينَةِ خَرَقَهَا\"\nفقال له: انت خرقت السفينة عشان تغرق الناس\nيعني هو ده جزاؤهم عشان ركبونا معاهم بدون أجرة ...هو ده رد الجميل\n\"قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْئًا إِمْرًا\"\n☆ده موسى يا جماعة\n...ميقدرش يشوف الغلط ولا الظلم ويسكت\nفغلبته عادته في الأمر بالمعروف والنهي عن المنكر ورفضه للسكوت عن الظلم ،وانتم أكيد فاكرين لما قتل المصري عشان ظن إنه ظالم للرجل إللي كان من بني إسرائيل،\nوفاكرين لما سقى للمرأتين وهو ميعرفهمش...فإزاي طبعا هيسكت على رجل يعتبر في وجهة نظر موسى إنه عايز يغرق الناس ومش أي ناس كمان دول الناس إللي ساعدوهم\nفالخِضر بص له وقال له:\nمش قلت لك إنك مش هتقدر تستحمل الصبر على عدم تفسير الحكمة\n\"قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا \"\nفتذكر موسى عليه السلام الشرط إللي كان بينهم وقال له : معلش المرة دي نسيت، متآخذنيش.. فسامحه الخِضر..\n\"قَالَ لَا تُؤَاخِذْنِي بِمَا نَسِيتُ وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا\"\nنزلوا من السفينة وكملوا الطريق.. ومشيوا لحد ما وهمّ ماشيين شافوا أطفال بيلعبوا... ، فراح الخِضر واخد منهم وراح قتله، يُقال إنه ضرب راسه بالجدار فقتله، ويقال إنه ضرب راسه بحجر\nموسى عليه السلام اتصدم\n...قال له:\nانت قتلت نفس بريئة بدون أي ذنب ولا حتى قصاص ؟!ده انت عملت منكر عظيم جدا \n\"فَانطَلَقَا حَتَّىٰ إِذَا لَقِيَا غُلَامًا فَقَتَلَهُ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْئًا نُّكْرًا\"\nفهنا الخضر أكد عليه تاني وقال له: مش أنا قلتلك إنك مش هتقدر تصبر \n \"قَالَ أَلَمْ أَقُلْ لَكَ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا\"؟\nموسى عليه السلام هيقول إيه المرة دي\nمش هيقدر يقول له عدِّيها دي كمان، حياؤه عالي ومروءته وأخلاقه أعظم من حبه الشديد لطلب العلم،\nوفعلا الأخلاق أهم في الأولوية من العلم،\nفموسى قال له عشان ينصفه من نفسه:\nلو سألتك عن حاجة تانية خلاص متصاحبنيش وكل واحد هيروح لطريقه.. \n\"قَالَ إِن سَأَلْتُكَ عَن شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي ۖ قَدْ بَلَغْتَ مِن لَّدُنِّي عُذْرًا\"\nهل ياترى موسى عليه السلام التزم بوعده للخضر؟\nولاّ مقدرش يستحمل وخلَف الشرط مرة ثالثة؟\nده إللي نعرفه المره الجايه ان شاء الله"}, {"n": 25, "l": "الجزء ٣٤ | قصة موسي ٩ | موسي والخضر | الجزء ٣٥ | يوشع بن النون", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الرابعة_والثلاثين\n#قصة_موسى_الجزء_التاسع\n#موسى_والخضر\nكنا واقفين المرة إللي فاتت عند موسى عليه السلام لما قابل الخِضر وشاف منه حاجات من وجهة نظر موسى عليه السلام كانت منكرة وعظيمة،\nوبعد ما موسى عليه السلام اعترض على أفعال الخضر مرتين  قال موسى عليه السلام للخضر إنه مش هيسأله عن حاجة تاني،\nكملوا بقى رحلتهم لحد ماوصلوا لقرية، وكانوا محتاجين ياكلوا، فطلبوا الضيافة من أهل القرية فمحدش منهم رضي إنه يضيّفهم،\nودي قاعدة في جميع الشرائع حتى الإسلام، إن أي حد يدخل المدينة غريب وعابر سبيل، واجب على أهل المدينة دي إنهم يضيفوا الزائر ده يوم وليلة. \nفهمّ لما دخلوا المدينة وطلبوا الضيافة كانوا بيطلبوا حق من حقوقهم مش بيطلبوا صدقة يعني، وأصلا الأنبياء لا تأكل الصدقة، \nفحتى من غير ما كانوا يطلبوا كان من المروءة إن أي حد من أهل المدينة لما يشوف حد سافر عابر سبيل داخل القرية هيعرضوا عليه الطعام والمبيت.. لكن دول محدش فيهم ضايفهم أو أعطاهم أي حاجة،\n\"فَانطَلَقَا حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَن يُضَيِّفُوهُمَا \"\nفموسى عليه السلام ومعاه الخضر سابوهم وراحوا يتمشوا في القرية،\nوهم ماشيين شافوا جدار فاضل له حاجة بسيطة وهيقع خلاص،\nفالخضر عَدَله عشان ميقعش، سواء بقى جاب مواد بناء ورمم بيها الجدار، أو إنه مَرّر عليه إيده فاتعدل بقدرة الله ومعجزة ، الله أعلم..\n\"فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَنْ يَنقَضَّ فَأَقَامَهُ\"\nفموسى عليه السلام معجبوش إللي حصل وقال للخِضر: انت كده عملت معروف للناس إللي رفضوا يضيّفونا بأقل شيء، طيب على الأقل اطلب منهم أجر، أو حتى اطلب الضيافة مقابل إصلاح الجدار ده\n\"قَالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا\"\n فهنا الخِضر رد على موسى وقال له:\nخلاص كده... احنا هنفترق.. ومش هنكمل مع بعض الرحلة \n \nلإنك للمرة التالتة مقدرتش تصبر زي ما قلتلك من الأول..\nلكن قبل ما أسيبك هقولك تفسير الحاجات إللي أنا عملتها كلها\n\"قَالَ هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا\"\nوبدأ الخضر يحكي لموسى عليه السلام أعاجيب الأقدار والحكمة...\nقال الخضر لموسى:\n\"أَمَّا السَّفِينَةُ فَكَانَتْ لِمَسَاكِينَ يَعْمَلُونَ فِي الْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَاءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا\"\nيعني بيقوله فاكر السفينة إللي ركبنا فيها...دي كانت بتاعة ناس مساكين بيشتغلوا عليها ومعندهمش غيرها،\nففي طريق رحلتهم هيعدّوا على أرض بتاعة ملك ظالم،\nوالملك الظالم ده كل ما بيشوف سفينة كويسة مفيهاش عيوب بياخذها بالغصب من أصحابها،\nفأنا عملت فيها عيب عشان لما جنود الملك يشوفوها يسيبوها للمساكين... لإن سفينة معيوبة بالنسبة لهم أحسن من لو مفيش سفينة خالص يسترزقوا منها\n☆وده يعلمنا إيه\nيعلمنا إن ما لا يُدرك كله لا يُترك جُله\nمش لازم كل حاجة تبقى تمام التمام.. مش لازم أستنى لما الأمور تبقى 100% عشان أشتغل، وإلا مش هشتغل لحد ما الظروف تبقى زي مانا عايز\nيعني لو مثلا مبقدرش أصلي قيام الليل ١٢ ركعة بـألف آية إللي بيهم أُكتب عند الله من المُقنطرين،\nولا حتى بقدر أقوم الليل بـمائة آية إللي بيهم أُكتب عند الله القانتين، على الأقل هصلي ركعتين بـعشر آيات قبل ما أنام،\nآخذ بيهم وعد من ربنا إن اسمي متشال في الليلة دي من الغافلين، \nزي ما رسول الله ﷺ قال في الحديث:\n\"من قام بعشر آيات لم يكتب من الغافلين، ومن قام بمائة آية كُتب من القانتين، ومن قام بألف آية كُتب من المقنطرين\"\n أنا مثلا بكسل أصلي سنن الصلاة يبقى أسيبها خالص \nلأ طبعا ...هصلي السنن وأنا قاعدة\nآخذ نص الأجر ولا إني أسيب الأجر كله\nهصلي إللي أقدر عليه من السنن ومش هسيبها كلها لعل ربنا يقويني بعزيمتي وأكمل.\nطيب واحدة مش بتعرف تقرأ قرآن بالترتيل... تسيب قراءة القرآن..؟ برده لأ .. تقرأ زي ما بتعرف وفي نفس الوقت تتعلم واحدة واحدة تقرأ بترتيل\n◇بس استنوا \nمش معنى كده إننا بنتكلم عن فِعل المستطاع من الفرائض\n لأ، احنا بنتكلم عن السنن والنوافل وفضائل الأعمال،\nلكن الفرائض لازم تكون تامة مافيهاش حتة آه وحتة بعدين، والمنكرات المحرمات هي كمان لازم نسيبها كلها مرة واحدة هي كمان\n \nالخضر كمّل تفسيره للأحداث وقال:\n\"\"وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَا أَن يُرْهِقَهُمَا طُغْيَانًا وَكُفْرًا \"\nفاكر يا موسى الطفل إللي أنا قتلته؟\nالطفل ده لما كان هيكبر كان هيكون كافر ورجل طاغية، وأمه وأبوه أصلا من المؤمنين، \nفكان هيتعبهم جامد لما يكبر ويكسر قلبهم أكتر من دلوقتي وكان ممكن يفتنهم عن الإيمان وتبقى الطامة الأكبر على الإطلاق،\nفرحمة من ربنا بيهم إنه أمر بقتل ابنهم وهو صغير لسه، وربنا هيعوضهم بواحد أحسن منه في الدنيا \n☆وطبعا هنا هييجي سؤال:\n هو ينفع طفل يُقتل عشان هيكون كافر في المستقبل\nبدايةً كده، الخِضر على أرجح أقوال العلماء إنه كان نبي مش مجرد رجل صالح، فلو أخدنا بالقول ده هيبان الجواب،\nلإن نبي تاني يعني عنده شريعة مختلفة بأحكام مختلفة لقومه، \nفشريعته تختلف عن شريعة الإسلام وتختلف عن شريعة موسى عليه السلام،\nفاحنا في شريعتنا وشريعة موسى عليه السلام كون إن الأبوين صالحين والابن فاسد فهذا ليس سبب لقتل الولد طبعا،\nلكن ده كان موجود في شريعة الخِضر... ومش بس كده،\nده كان قتل الغلام ده بأمر مباشر من ربنا\nوربنا أمر بقتله لأن الأباء بيحبوا أبناؤهم حب فطري شديد، فعشان في المستقبل حبهم ده ميكونش سبب إنهم يتّبعوا ابنهم في الضلال،\nوفي أوقات كتير الفتنة بتيجي من زوجة لزوجها، أو العكس، أو من الولد لأبوه وأمه.. ربنا بيقول:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ عَدُوًّا لَّكُمْ فَاحْذَرُوهُمْ ۚ\"\nوده بيحصل في زماننا دلوقتي،وأكيد كلكم تعرفوا قصص واقعية عن ده\nمش شرط يكون اتباع الأبناء في الكفر فقط...لكن بيكون كمان في المعاصي.. \nتلاقي البنت طالعة من البيت لابسة هدوم غير ساترة ، ومتبرجة بزينة ومتعطرة و...و...\nولما نكلم الأم ولّا الأب يقول: أصلها مش راضية، أصلها بتزعل لما بفتح الموضوع ده معاها\nطيب وهي أصلا جابت الفلوس إللي اشترت بيها اللبس ده منين\nماهو الأب والأم همّ إللي دفعوا الفلوس دي\nعلى الأقل امنع الفلوس إللي هي تشتري بيها الحاجات دي،\nوممكن يقول: أصل احنا مش عايزين نغصب عليها وعايزينها تعمل كده عن اقتناع\nيعني أيها الأب العزيز ويا أيتها الأم الغالية:\nلو بنتك جابت إزازة بنزين وجت تولع في الشقة هنسيبها لحد ما نقنعها إنها ماتولعش في البيت \n \nأكيد الأم ولّا الأب هيوقفوها بكل الطرق الممكنة حتى لو بالغصب، ويمكن يلمّوا الشارع كمان بالمرة يساعد معاهم\nطيب دي نار الآخرة مش هزار\nلبس البنات إللي ميرضيش ربنا ده، والمعاصي إللي البنات والولاد بيعملوها دي وأهلهم راضيين عنها أو حتى مش بياخدوا خطوات عملية عشان يمنعوا أبناؤهم عنها و فاتحين لهم نت وألعاب فيها منكرات وأجهزة يشوفوا عليها كل الخبائث بدون أي رقيب، كل ده وغيره، في ميزان سيئاتهم يوم القيامة، \nوالحجة إيه لكل ده؟ عشان ميبقاش أقل من صحابه\nلو أنا كأم أو أب شوفت بنتي ولا ابني هيرمي نفسه من البلكونة عشان عاوزة تطير زي العصافير، هسيبهم ولّا هشدهم جااامد عشان أنقذهم من الموت؟\nطيب شدوا أبناؤكم جااااامد أوي ولو غصب عنهم عشان تنجوهم وتنجوا نفسكم من النار \n \"يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ \"\n¤عدنا كمان سؤال تاني، \nهل معنى كده إن أي أم وأب لهم طفل بيموت صغير أو يُقتل إنه كان هيبقى كافر في المستقبل\nمش شرط لإن العلم عند ربنا...ممكن يكون إنه لو بلغ خلاص هيبقى عذاب على أمه وأبوه،\nوممكن العكس... يعني كان ممكن يعيش في شقاء وعذاب بسبب فساد أمه وأبوه،\nأو ربنا أراد إنه يأجر الأم والأب بوفاة ابنهم ويكون سبب لدخولهم الجنة، حِكَم إلهية كتير ملهاش حدود\nلكن الأصل بصفة عامة إن أي حد من أبناء المسلمين يموت في سن صغير قبل سن التكليف فهو من أهل الجنة في كفالة إبراهيم عليه السلام حتى يدخلوا الجنة مع أباؤهم،\nلاااااكن مينفعش نقول على طفل بعيينه \"فلان بن فلان\" ده إنه من أهل الجنة\nيعني لو ابني مات صغير ماينفعش أقول ابني ده من أهل الجنة خَبط لزق كده ، أقول أتمنى إنه يكون من أهل الجنة \nزي ما رسول الله ﷺ  بشّرنا،\nوأدعيله طبعا بكده.. والدليل على كلامنا ده \nإن الأنصار جاءوا بصبيٍّ لهم إلَى النَّبيِّ ﷺ عشان يصلوا عليه فقيل لرسول الله ﷺ:\n\"هَنيئًا لَهُ يا رسولَ اللَّهِ ، لم يَعمَل سوءًا قطُّ ، ولم يُدرِكْهُ ، عُصفورٌ من عصافيرِ الجنَّةِ\"\nفرد رسول الله ﷺ: \n\"أو غيرُ ذلِكَ إنَّ اللَّهَ عزَّ وجلَّ لمَّا خلقَ الجنَّةَ ، خلقَ لَها أَهْلًا وَهُم في أصلابِ آبائِهِم وخلقَ النَّارَ ، وخلقَ لَها أَهْلًا وَهُم في أصلابِ آبائِهِم\"\nيعني محدش يعرف مين مصيره إلى الجنة ولا مين مصيره إلى النار،\nفمينفعش أبدا نشهد لشخص بعينه إنه من أهل الجنة ولا من أهل النار إطلاقا، لكن بصفة عامة زي ما قلنا كل مَن يموت من أطفال المسلمين فهو من أهل الجنة\n¤طيب وأطفال غير المسلمين\nدول حُكمهم إن ربنا هيمتحنهم يوم القيامة،\nزي كده الناس إللي لم تصلهم رسالة الإسلام هيكونوا لهم وضع مختلف،\nفلسه لهم امتحان في الآخرة همّ كمان فمينفعش نشهد لهم بالنار ولا بالجنة برده، لا بصفة عامة ولا بصفة معينة\nوالاختبار بتاع يوم القيامة ده هيكون شبه ابتلاءنا في الدنيا طبعا، فيه صعوبة واختبار حقيقي للإيمان، لكنه بصورة تانية.. ربنا عز وجل سيأتي بجزء من النار، \nوبعدين هيقول للشخص إللي هيُمتَحَن عشان يتحدد مصيره :\n\"إني كنت أبعث إلى عبادي رسلا من أنفسهم وإني رسول نفسي إليكم ادخلوا هذه\"\nيعني انتم موصلكوش رسول برسالتي وشريعتي، فالنهاردة أنا رسول نفسي إليكم، وبَأْمُركم إنكم تدخلوا في النار دي،\nفلو سمعوا كلام ربنا وأطاعوه هيبقوا مؤمنين وهيدخلوا الجنة،\nولو رفضوا وعصوه سبحانه، ربنا هيقولهم :\n\"أنتم لرسلي أشد تكذيباً ومعصية \" \nيعني في وسط الأهوال دي كلها والآيات الواضحة على استحقاق رب العالمين للعبودية والسمع والطاعة الكاملة،\nوظهور عدل ربنا ورحمته وصفاته الكاملة سبحانه، ومع ذلك بيقول لهم ادخلوا النار وميسمعوش كلامه! \nأومّال في الدنيا كانوا هيعملوا إيه\nوطبعا هيبقى مصيرهم النار \nنرجع لتفسير آخر نقطة في رحلة موسى مع الخضر، وكانت عن الجدار إللي في المدينة قال:\n\"وَأَمَّا الْجِدَارُ فَكَانَ لِغُلَامَيْنِ يَتِيمَيْنِ فِي الْمَدِينَةِ وَكَانَ تَحْتَهُ كَنزٌ لَّهُمَا \"\nيعني أما بقى الجدار إللي أنا رممته ده ، فكان في طفلين من الأيتام في المدينة الخبيثة دي، والجدار ده كان ملكهم وتحت منه كان فيه كنز بتاعهم،\nفلو كان الجدار وقع، أهل القرية كانوا هياخدوا كنز الأيتام ده،\nلكن ربنا أراد إنه يحفظ حق الأبناء دول لحد ما يكبروا ويطلعوا همّ الكنز بتاعهم بلطفه وتدبيره المعتاد عز وجل.. والمعروف ده كان إكرام ليهم من ربنا لإن أبوهم كان رجل صالح\n\"وَكَانَ أَبُوهُمَا صَالِحًا فَأَرَادَ رَبُّكَ أَنْ يَبْلُغَا أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ \"\n☆ودي رسالة للناس إللي بتخاف على عيالها من المستقبل، وتضيع عمرها عشان تِأمّن مستقبلهم ولو بالحرام زي أخذ رشاوي أو شراء شقق وعربيات ليهم بأقساط ربوية مثلا، وناسيين إن الحفظ ده رزق من الله هو الحافظ سبحانه،\nوالرزق إللي عنده مينفعش نستَجلِبه بمعصية، \nوكمان يعلمنا إننا مهما عملنا –حتى لو مكنش في معصية- فمش هنقدر نمنع قدر ربنا من إنه يحصل\nيبقى احنا نصلح نفسنا ونتقي الله في أقوالنا وأفعالنا وناخد بالأسباب الحلال المباحة إللي مرتبطة بحفظهم وأمانهم، ويكون أخذنا للأسباب دي من باب طاعة الله إللي أمرنا بكده، ثم بعدها نخلي عندنا يقين إن مش الأسباب هي إللي هتحفظهم لكن ربنا هو إللي هيحفظهم حتى لو إحنا مش موجودين عشان نحميهم..\nربنا بيقول:\" وَلْيَخْشَ الَّذِينَ لَوْ تَرَكُوا مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَافًا خَافُوا عَلَيْهِمْ فَلْيَتَّقُوا اللَّهَ وَلْيَقُولُوا قَوْلًا سَدِيدًا\"\nخايفين على عيالنا من المستقبل ، يبقى نصلح نفسنا وعلاقتنا مع ربنا وناخد بالأسباب زي ما قلنا، وهو عز وجل مش هيضيعهم\nربنا أرسل رسول من أولي العزم من الرسل ومعاه نبي تاني   عشان يرمموا جدار لطفلين يتيمين عشان بس أبوهم كان صالح وفي رواية:\nالمقصود بالأب ده هو جدهم السابع كمان مش مجرد أبوهم! ...يعني لما نصلح نفسنا، مش بس ربنا هيحفظ لنا عيالنا، ده كمان هيحفظ لنا أحفادنا وأحفاد أحفادنا إلى ما شاء الله بحول الله وقوته.\nختم الخضر كلامه مع موسى بإن كووول إللي هو عمله ده كان بوحي وأمر من ربنا له، وإنه معملوش من تلقاء نفسه \n\"وَمَا فَعَلْتُهُ عَنْ أَمْرِي ذَلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا \"\nوبكده خلصت الرحلة العجيبة مع الخضر، إللي لو كان موسى عليه السلام صبر شوية زيادة كان اتعلم منها أكتر وأكتر،\nزي ما رسول الله ﷺ قال:\n \"رحمةُ الله علينا وعلى موسى، لو صَبَر على صاحبه لرأى العجب، لكن أخذتْه مِن صاحبه ذمامةٌ\"\nيعني موسى عليه السلام خاف إنه يقع في الذم والحرج من الخِضر بسبب تكرار نسيانه فقال:\n \"إِنْ سَأَلْتُكَ عَنْ شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِنْ لَدُنِّي عُذْرًا\"\n☆الكلام إللي قلناه ده يعلمنا حاجة مهمة أوي:\nوهي إننا منحكمش على أي حد من وجهة نظرنا احنا بس...لازم نفهم من الطرف التاني وجهة نظره،\n يمكن هو شايف حاجة احنا مش شايفينها، ويمكن وجهة نظره هي إللي صح واحنا إللي غلطانين..\nفقبل ما نحكم وناخد قرار أو نحط حُكم، لازم نشوف الصورة كاملة الأول ومن كل  الزوايا\nفكل إللي موسى عليه السلام شافه من الأحداث إللي تعتبر ضد المنطق والعقل والمروءة بالنسبة له اتضح إن ليها حكمة، \nوكل الحاجات إللي بنشوفها ممكن نفهم حكمتها وممكن منفهمش، \nلكن أهم حاجة إننا نسلم أمرنا لله لأن كل حاجة في الكون بتحصل بأمر من الله وبعلمه وحكمته وتدبيره سبحانه، وإللي عمرنا ما هنعرف مقدارهم بعقلنا القاصر ده\nانتهت رحلة موسى مع الخِضر، ورجع موسى عليه السلام لقومه وفضل معاهم تاني يعلمهم دينهم ويأدبهم..\nشوية يجتمعوا ويتعظوا، وشوية يُعرضوا وينتكسوا، مذبذبين بين ذلك لا إلى هؤلاء ولا إلى هؤلاء.. \nواستمر الحال كده لحد قبل نهاية زمن التيه بست سنين، ساعتها هارون عليه السلام مات وهو عمره ١١٧ سنة..\nوعاش موسى عليه السلام بعده ثلاث سنوات، ثم في يوم من الأيام ،دخل فجأة على موسى عليه السلام رجل، وقاله :\n\"أجِب ربك\"\nيعني سلمني روحك\nفموسى عليه السلام اتخض ، وافتكره واحد جاي يقتله! فضربه موسى عليه السلام ففقع له عينه\nمن حقه طبعا يدافع عن نفسه لإن ده واحد داخل عليه البيت فجأة بدون إذن وبيقول له سلمني روحك \nفكان الرجل ده هو ملك الموت وكان ربنا أرسله عشان يقبض روح موسى عليه السلام وكان جايله في صورة رجل بشري مش في صورة الملك المعروفة عشان كده فقع عينه،\n وكمان موسى عليه السلام مكنش لسه خُيّر، لأن الأنبياء لا تُقبض أرواحهم إلا لما ربنا يخيرهم هل عايزين يعيشوا في الدنيا ولا يموتوا ويدخلوا الجنة، فموسى عليه السلام متوقعش أبدا إن الرجل ده هو ملك الموت،\nفملك الموت رجع لربنا وقاله :\nبعثتني لرجل لا يريد الموت! \nهو بيقول كده لإنه فاكر إن موسى عليه السلام عارف إنه ملك الموت فضربه عشان رافض الموت،\nفربنا رد عليه عينه في الهيئة البشرية وقاله ارجع تاني لموسى وقوله:\nحط إيدك على ظهر ثور وكل شعرة هتمسّها إيدك ليك بكل واحدة منها عُمر سنة،\nفرجع ملك الموت في نفس الهيئة لموسى عليه السلام ، فلما موسى شاف إن عينه رجعت زي ماكانت عرف إن ده مش شخص عادي، فبلغه ملك الموت رسالة ربنا،\nفقال موسى عليه السلام:\nطيب وبعدين...يعني بعد ما أعيش السنين دي كلها إيه النهاية؟\nفقال له : الموت...فقال موسى عليه السلام : فالآن.\nيعني خلاص أختار ان تُقبَض روحي دلوقتي،\nودعا ربنا إنه يقربه من الأرض المقدسة مقدار رمية حجر،\n فمات موسى عليه السلام واندفن بالقرب من الأرض المقدسة إللي رفض بني إسرائيل يدخلوها فقبره خارج فلسطين وليس داخلها زي ما بيتقال.\nإيه إللي حصل لبني إسرائيل بعد موت موسى عليه السلام ؟\nومين هو النبي إللي استلم النبوة بعد موسى عليه السلام؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء\n#الحلقة_الخامسة_والثلاثون\n#يوشع_بن_نون\nوقفنا المرة إللي فاتت عند موت موسى عليه السلام، وكان موته قبل نهاية فترة التيه بحوالي ثلاث سنوات،\nموسى عليه السلام كان يعلم يقينًا إنه هيموت في يوم من الأيام، فكان لازم يشوف حد يقود بني إسرائيل من بعده،\nوطبعا الشخص ده لازم يكون له صفات معينة عشان يقدر يتحمّل بني إسرائيل وإللي بيعملوه\nفكان في فتى ظاهر عليه دلائل النباهة والصبر والطاعة لله، فاهتم بيه موسى وهارون عليهما السلام، وكان بيصاحب موسى عليه السلام على طول عشان يتعلم منه.\n☆ودي هي التربية بالقدوة هو ممكن يعلمه تعليم نظري لكن لازم يتعلم إزاي يطبّق...وهيطبق إزاي من غير ما يكون شايف حد قصاده بيطبق الكلام إللي بيتعلمه وبيتابع تطبيقه للكلام النظري\nيعني مثلا موسى عليه السلام بيعلمه الصبر... فالدرس العملي بتاعه إنه يشوف صبر موسى على بني إسرائيل،\nفالتربية بالقدوة هي أصل التربية، وهي دي الطريقة إللي رسول الله ﷺ ربّى بيها الصحابة،\nعايزين تربوا عيالكم على حب القرآن وحفظه وقراءته، يبقى لازم يشوفوا ده فيكم انتم الأول\nعايزين تربوهم على احترام المواعيد والوعد، وعلى التقوى وحب الله والصدق وعدم الكذب... لازم يشوفوا ده فيكم الأول برده......\nالأبناء كاميرا مُسَجِّلة ، بتسجل كووول حاجة بيشوفوها من الكبار، والأباء والأمهات بالذات وعلى الأساس ده بيتصرفوا.\nفكان الفتى أو الشاب ده بيتبع موسى عليه السلام وكان موسى بيثق فيه لدرجة إنه لما راح قابل الخِضر أخده معاه،\nوالفتى ده كان اسمه يوشع بن نون وهو من ذرية يعقوب عليه السلام،\nفبعد ما موسى عليه السلام مات هو إللي تولّى أعباء النبوة،\nفبقى هو إللي بيوجّه بني إسرائيل وبيعلمهم، واستمر يبلّغ شريعة موسى عليه السلام بكل حرص وإخلاص،\nبعد ما عدت الأربعين سنة كان الجيل خلاص اتغير.. فالجيل إللي قال قبل كده لموسى عليه السلام \"اذهب أنت وربك فقاتلا إنا هاهنا قاعدون\" اختفى أثره نوعًا ما،\nفمنهم إللي مات ومنهم إللي خلاص كِبِر في السن، ده غير إن منهم إللي اتغيرت واتأثرت عقلياتهم بشكل إيجابي بكلام موسى بسبب الأحداث إللي شافوها خلال السنين إللي فاتت بالفعل،\nفدلوقتي بقى فيه جيل جديد موجود غير الجيل الأول،\nهو أه الجيل ده نتاج تربية الجيل القديم لكن على الأقل مش زيهم\nيعني مشافوش الذل والقهر والاستعباد واتعوّدوا عليه زي الأجيال السابقة،\nفكان يوشع عليه السلام بيعلم الجيل الجديد ده القتال وبيعلمهم طاعة الله،\nعشان لما ينتهي زمن التيه يروح يقاتل الجبّارين إللي في بيت المقدس ويسترجعوا الأرض منهم.\nفبعد ما انتهى زمن التيه... أمر بني إسرائيل إنهم يخرجوا معاه للجهاد،\nلكن يوشع عليه السلام حط شروط للناس إللي هيخرجوا معاه للجهاد،\n◇أول شرط:\nمش عايز في الجيش واحد عَقَد على امرأة عقد نكاح ولم يبنِ بها بعد.. يعني مش عاوز من ضمن الجنود إللي هتروح حد يكون كاتب كتابه فقط بدون إتمام زواجه بزوجته لسه.\n◇ثاني شرط:\nمش عايز واحد بنى بيت ولسه مكملش بناء السقف.\n◇ الشرط الثالث: \nمش عايز واحد اشترى غنم وهو مستني الغنم ده يولد.\n☆طيب ليه الشروط دي\n ما ياخدهم معاه كلهم وخلاص هو لاقي حد يروح بطيب نفس أصلا عشان يجازف بتقليل العدد أكتر\nطبعا ده تفكيرنا المنطقي، يعني الواحد في الوقت ده بيكون محتاج أي حد معاه\nبس التفكير ده غلط.. لإن الجيش إللي مفروض يكون جيش النصر، مش الممفروض يكون فيه 《أي حد》 و نكَتّر العدد وخلاص،\nلأن بكل بساطة المؤمنين على مر العصور مش بينتصروا بعدد أبدا لكن بينتصروا بالإيمان وبطاعة الله وتقواه\nأيوة بياخدوا بالأسباب العددية الدنيوية طاعةً لله ، لكن النصر كده كده من عند ربنا،\nيعني مثلا الرجل العاقد على المرأة ده هيبقى قلبه متعلّق بيها، \nهيبقى عايز يرجع لها بسرعة عشان يكمل إجراءات الزواج ويروح بيته بقى ويخلف ويعيش حياته،\nفنتخيل لو مكنش قال الشرط ده وبقى في الجيش آلاف من الشباب دي إيه إللي هيحصل؟\nكان أول ما هيشوف السيف وإنه خلاص ممكن يموت هتلاقيه انسحب فورا أو على الأقل اشتغل في تثبيط إخوانه ونشر روح الهزيمة،\nفلو انسحب الآلاف دول إللي القائد عامل حسابه عليهم كقوة مهمة من ضمن قوات الجيش بتاعه من باب الأخذ بالأسباب، إيه إللي ممكن يحصل؟\nهيحصل خلل رهيب في الجيش\nنضيف عليهم بقى الصنف التاني والثالث،\nالناس إللي بنوا بيت ولسه مكملوهوش، و إللي اشترى أغنام ومستني إنها تولد،\nكل دول أول ما هيشوفوا هول المعركة هينسحبوا غالبا ويسيبوا الجيش هزيل المنظر قليل العدد يواجه الجبارين دول لوحدهم\nومش كده وبس ده ممكن الجيش الرئيسي يتأثر بالانسحاب ده وينسحب معاهم المؤمنين \n☆زي مثلا في الواقع بتاعنا لما تيجي تنصح واحد ويقول لك ماالناس كلهم كده\nهو همته ومقاومته وثباته وعزيمته ضعفوا لما لقى من إللي حواليه ناس تراجعوا عن الحق وتركوه،\nفده بيبقى زي العدوى إللي بتنتقل للباقيين وتأثر عليهم.. عشان كده ديننا شرع الحدود مثلا، عشان اللي عاوز يغلط يروح يستخبى من الخلق ومينشرش غلطه قدام عنيهم علنا وجهرًا فيفتنهم إنهم يقلدوه\nوطبعا دي مش دعوة لمعصية الله في السر، بالعكس، أعظم أبواب الخسران بتكون ذنوب الخلوات لإن الواحد نسي فيها إن الله سميع بصير شهيد..\n لكن إشاعة الغلط بين الناس جريمة أكبر لإنه أشد أثرا بالفتنة للجميع.\nفمع الكلام إللي قلناه ده زيدوا بقى عليهم إن بني إسرائيل \nفيهم حتة التعلق بالأمور المادية المحسوسة دي جدا،\nوده من أقوى أسباب تعلقهم بالدنيا، وربنا قال عنهم ربنا\n\"وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلَى حَيَاةٍ\"\nشوفوا كلمة 《حياة》 دي، هم عايزين أي حياة وخلاص، عشان كده يوشع شدد على الشروط إللي قلناها دي،\nفيوشع عليه السلام مش عايز يعرّض جنوده للفتنة والهزيمة وخصوصا إن لسه في بعضهم محتاج تربية إيمانية،\nوقوة بني إسرائيل وحجمهم أقل من قوة الجبارين بالفعل وهم قلقانين من ده، \nفلازم ياخد بأسباب النصر العقلية، ومنها إن محدش يدخل معانا في الجيش وقلبه متعلق بأي هموم تخص الدنيا ،\nفمش هينفع أي مخاطرة بأي حال من الأحوال\nبعد ما يوشع عليه السلام جمع الجيش ، عدى على بحر الأردن ، لحد ما وصل لأَرِيحا المحتلة الآن من اليهود،\nوكانت أريحا من أحصن المدائن في الأسوار وأعلاها في القصور وكان أكثر الجبارين عايشين فيها،\nفحاصرها يوشع ست شهور،\nوفي يوم من أيام الشهر السابع ،حاوطوا المدينة وقعدوا ينفخوا بالأبواق، ويكبّروا في نَفَس واحد،\nفالسور شَقَّق و انهار على الأرض، فدخل يوشع والجيش إللي معاه، وقاتلوا الجبارين وقتلوا منهم ١٢ ألف ،\nوكان الكلام ده في يوم الجمعة... فلما خلاص أوشك على الإنتصار كانت نهاية يوم الجمعة بعد العصر،\nفلو غربت الشمس يبقى كده هيدخلوا في ليلة السبت، ويوم السبت ده في شريعة موسى ويوشع عليهما السلام  إن بني إسرائيل ممنوع يحاربوا فيه، \nفدلوقتي لو انسحب يوشع بجيشه ورجع بسبب يوم السبت ، يبقى الجبابرة هيستعيدوا قوّتهم ويلموا عتادهم ويتعلموا من أخطاؤهم ويتجمعوا من تاني ويهجموا على جيش يوشع ويخلصوا عليهم، \nوفي نفس الوقت يوشع عليه السلام مش عايز يعصي أمر ربنا باستمرار القتال لحد ما يتم استرجاع البلد تاني من إيدين الجبارين، مع إنه بيقاتل برده لأمر ربنا\nفعمل إيه؟\nبص للشمس وقال لها :\nانتِ مأمورة إنك تغربي زي كل يوم ، وأنا مأمور إني أفتح المدينة ومأمور إني لا أقاتِل يومَ السبت ،\nثم بدأ يدعي ربنا: يارب احبسها وماتخليهاش تغرب لحد ما أكمل المعركة\nفربنا استجاب ليوشع وفعلا حبس الشمس وخلاها موجودة لحد ما أنهى يوشع المعركة وانتصر على الجبارين،\nفيوشع هو النبي الوحيد إللي حُبست له الشمس كما في حديث رسول الله ﷺ:\n\"إِنَّ الشَّمْسَ لَمْ تُحْبَسْ لِبَشَرٍ إِلَّا لِيُوشَعَ لَيَالِيَ سَارَ إِلَى بَيْتِ الْمَقْدِسِ\"\n☆قلتلكم قبل كده إن ربنا بيحكي لنا القصص عشان نعتبر\n وناخد الخلاصة ومنقعش في نفس أخطاء الأمم السابقة،\nطيب إيه العبرة من قصة يوشع إللي ربنا يريد إننا نتعلمها\nحصل مع يوشع عليه السلام إنه تعارضت طاعتين مفروض يؤديهم لله، أمرين من أوامر ربنا...\nفكان رد فعله إيه؟\nهل ضحى بأمر من أوامر ربنا على حساب التاني وقال أصل انا مضطر؟ وهو فعلا مضطر بالمناسبة\nولّا نفذ الأمرين مع بعض وهو مستعين بالله\nطيب خلونا ناخد مثال من حياتنا اليومية\nبر الوالدين وطاعتهم في المعروف واجبة، صح؟\nوإللي أمرنا بده هو الله.. تمام؟\nطيب لما أمي أو أبويا أو حتى زوجي يطلبوا مني حاجة مخالفة للشرع إللي هو برده أوامر ونواهي ربنا،\nسواء يعترضوا على لبسي للنقاب، أو يطلبوا مني إني أحضر فرح فيه اختلاط ومنكرات ما ترضيش ربنا،\nأو زوجي يطلب مني إني أقعد اتفرج معاه على أفلام ومسلسلات أو أمد إيدي وأسلم على ابن عمه مثلا أو...أو...وربنا أمرني إني معملش كده،\nيبقى أنا المطلوب مني إيه هنا؟\nأنا المطلوب مني إني أطيع أبي وأمي في غير معصية الله،\nلكن للأسف في الواقع بيحصل التضحية بواحد من الاتنين وبيحصل الشقاق معاه، إلا من رحم الله،\nالمفروض أستعين بالله وأراضيهم وما أعملش شقاق وما أحسسهمش إنهم كفرة أو أهل فسق وأنا إللي صَحابي وقديس في نفسي كده،\nوفي نفس الوقت أنفذ أمر ربنا ومعملش المعصية وعمري ما أضحي بده ولو على جثتي، \nومع ده وده أدعي ربنا إنه يساعدني عشان أعمل الطاعتين مع بعض بدون ما حد يفتني في ديني منهم وبدون ما أدخل مع حد فيهم في شِقاق ومشاكل ممكن يؤدي لخصام وفرقة والعياذ بالله،\nساعتها لو ده تفكيرك وكنت حريص بصدق على الاتنين إرضاءً لله، هتلاقي ربنا سخر لك قلوبهم بالرضى زي ما سخر الشمس ليوشع وحبسها له\nعارفين بقى المشكلة في إيه\nالمشكلة بتبقى جوانا ..إما إننا مش صادقين أوي في إننا عايزين فعلا نعمل الطاعتين زي يوشع عليه السلام، \nأو بيبقى في شك كده في قدرة ربنا مش باين والعياذ بالله،\nشك إن ربنا ممكن يعمل لي معجزة على أدي تقلب الوضع عكس ما أنا  تخيلته وعكس ما تبدو عليه الأمور،\nيعني بييجي جوانا ساعات نقول طيب ماشي ما أنا بدعي بس أصل صعب ده يحصل، أو طيب أنا هدعي وأشوف أما أجرب كده\nوربنا مينفعش معاه التجربة أبدا...لازم ندعي بيقين..فتلاقي للأسف بالرغم إنك بتدعي مفيش نتيجة\nوالناس إللي مش فاهمة بتتهم ربنا بقى ...هو ليه ماستجبليش هو ليه مساعدنيش...ومش فاهمين إن فيه سنن كونية ربنا بيدبرها وبيدبر أمرك وإنت مش حاسس ولسه مش شايف ده، \nوإنه عز وجل لا يعجل بسبب استعجال حد، \nوممكن يوصل بعضهم في النهاية إنه يلحد والعياذ بالله... يعني يحصل له بلاء، ومش فاهم حكمة ربنا منه، \nفيقول ده ربنا ده مش عدل –حاش لله- أعطى غيري كذا وحرمني أنا منه، \nويفضل بقى في دوامة من الشك والريبة والعياذ بالله ومش فاهم إن العيب من نفسه هو ومن منهجه في التفكير\nفلما يحصل لك زي يوشع بن نون كده ويتعارض أمرين من أوامر الله...اصدق مع ربنا من قلبك إنك عايز تعمل الأمرين دول وادعي ربنا إنه يعينك ويساعدك على كده وهتشوف العجب والله\nانتصر يوشع عليه السلام على الجبابرة، وجمعوا الغنائم إللي هي كل حاجة الجيش بيكسبها و يغتنمها من جيش العدو المهزوم بعد انتهاء المعركة، سواء بقى دهب أو فضة أو أغنام أو أسلحة أو خيول..كل حاجة، \nوزمان في الشرائع قبل الإسلام الغنائم دي كانت تتجمع وتنزل نار من السماء تاخذها، زي قُربان قابيل وهابيل كده لو تفتكروا\nلكن في شريعة الإسلام ربنا أحل الغنائم للمسلمين، يعني تتوزع على المسلمين بتقسيمة معينة بينهم مش موضوعنا النهاردة\nفاللي يهمنا إن يوشع جمع الغنائم عشان نار تيجي تاخدها،\nفاستنوا النار تنزل كالعادة، منزلتش\n!\nفيوشع عليه السلام قال: \nفي حد منكم غَلّ من الغنائم، يعني أخد من الغنائم دي حاجة لنفسه من غير ما حد يعرف... \nفمحدش رد، فقال لهم يوشع عليه السلام:\nكل سِبْط يبايعني منه النقيب بتاعه\nيعني الأسباط إللي هم ذرية أبناء يعقوب عليه السلام ال12\nكل سِبط أو قبيلة منهم لها نقيب ينوب عنها، زي قائد المجموعة كده،\nفبدأ الـ١٢ نقيب يبايعوا يوشع بإيدهم واحد واحد، يعني كل واحد بيحط إيده في إيد يوشع كأنه بيسلم عليه،\nفا وهو بيبايع نقيب منهم ،إيده لزقت في إيد يوشع!\nفقال يوشع : الغلول في السبط ده!\nيعني في القبيلة إللي ورا النقيب ده، فبدأ يبايع قبيلة النقيب ده عيلة عيلة لحد ما إيده لزقت في رجلين ثلاثة،\nفقال لهم أنتم غللتم من الغنائم، يعني سرقتم من الغنائم،\nفجابوا له قطعة كده زي رأس بقرة من الذهب، كانوا فعلا واخدينها ليهم من الغنائم،\nفيوشع وضع الغنائم كلها مع بعض، فنزلت النار من السماء أكلت الغنائم،\n☆ودي آية مذهلة من ضمن الآيات إللي ليها دلالة واضحة في كل عصر وقعت فيه، وبالأخص أمام بني إسرائيل، على وجود الله ربنا عز وجل واستحقاقه وحده بالعبادة\nبعد كده ربنا أمر بني إسرائيل إنهم ييجوا يدخلوا المدينة عشان يعيشوا فيها،\nلكن قال لهم وانتم داخلين ادخلوا وانتم راكعين خاضعين لله شاكرين على الفتح العظيم ده واستغفروا لذنوبكم وقولوا حِطّة،\nيعني يارب حُط عنا خطايانا إللي فاتت من إعراضنا ورفضنا إننا ندخلها قبل كده من أربعين سنة\n  \n\"وَإِذْ قُلْنَا ادْخُلُوا هَٰذِهِ الْقَرْيَةَ فَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ رَغَداً وَادْخُلُوا الْبَابَ سُجَّداً وَقُولُوا حِطَّةٌ نَغْفِرْ لَكُمْ خَطَايَاكُمْ وَسَنَزِيدُ الْمُحْسِنِينَ\"\n☆بنو إسرائيل عملوا إيه بقى\nخالفوا الأمر طبعا كالعادة\nرغم كوووول الآيات الدالة بوضوح شديد على وجود الله واستحقاقه للطاعة!\nدخلوا زاحفين على مقاعدهم، إللي هي مؤخرتهم بكل أسف وسوء أدب، وقالوا حَبَّة في شَعرة، أو حِنطة في شَعرة\nأهه أي استهزاء بأوامر الله وضحك وتريقة وخلاص...متخيلين\nيقول النبي ﷺ : \n\"قيل لبني إسرائيل ادخلوا الباب سُجَّداً وقولوا حِطة، فدخلوا يزحفون على أَسْتَاهِهِمْ، فبدَّلوا وقالوا حبّة في شعرة.\" \nفربنا أرسل عليهم الطاعون والعياذ بالله، قتل منهم ٧٠ ألف بس وهمّ واقفين كده\n\"فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَنْزَلْنَا عَلَى الَّذِينَ ظَلَمُوا رِجْزًا مِنَ السَّمَاءِ بِمَا كَانُوا يَفْسُقُونَ \"\nوفي رواية تانية العدد ٢٠ ألف.. المهم إن ربنا عاقبهم على استهزاؤهم ده وتبديلهم لأوامر الله..\n \"قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ\"\nعاش بقية بني إسرائيل مع يوشع بن نون في بيت المقدس يحكم بينهم بالتوراة لحد ما مات وهو عمره 127 سنة.\nهل استمر بنو إسرائيل في بيت المقدس ولا حصلت أحداث تانية؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 26, "l": "الجزء ٣٦ | حزقيل_____الياس___اليسع", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_السادسة_والثلاثون\n#حزقيل_إلياس_اليسع\nوقفنا المرة إللي فاتت عند موت يوشع عليه السلام، بعد ما عاش في بيت المقدس فترة من الزمن مع بني إسرائيل يحكم فيهم بالتوراة،\nبنو إسرائيل من كثرة فسادهم وعصيانهم لله، كان ربنا بيبعث فيهم الأنبياء ..واحد ورا الثاني ورا الثالث؛ عشان يستقيموا على الدين وميبعدوش عنه،\nفبعد موت يوشع عليه السلام، انتقلت النبوة لنبي من بني إسرائيل اسمه《كَالِب بن يُوفَنا》...احنا منعرفش عنه حاجة تقريبا، لكن كباقي الأنبياء استمر يحكم في بني إسرائيل بحكم الله وشريعته لحد ما مات،\nوجه بعده نبي تاني اسمه حِزقِيل بن بُوذَى --ويقال إنها بُوذِي-- وبرده معندناش عنه أخبار كثيرة، \nلكنه كان نبي من أنبياء بني إسرائيل ، نعرف عنه قصة واحدة فقط، هي في قوله تعالى:\n\"أَلَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِن دِيَارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ فَقَالَ لَهُمُ اللَّهُ مُوتُوا ثُمَّ أَحْيَاهُمْ \"\nإللي هي قصتنا النهاردة..\nبعد يوشع عليه السلام انقسمت النبوة والملك، يعني قبل كده كان النبي هو الملك أو الحاكم إللي بيحكم بني إسرائيل،\nلكن بعد موت يوشع عليه السلام بقى في مَلِك أو حاكم يحكم بني إسرائيل، وفيه نبي تأتيه النبوة والرسالة والشريعة من ربنا،\nفكان فيه ملك معين من حُكام بني إسرائيل، أمرهم إنهم يقاتلوا عدو ليهم، منعرفش مين هو العدو ده\nلكن بني إسرائيل خافوا من القتال والموت بما إنهم طول عمرهم أحرص الناس على حياة، \nفاتحججوا و قالوا للحاكم بتاعهم إن القرية إللي انت عايز تودينا ليها دي فيها طاعون فمش هندخلها\nفربنا أنزل عليهم الطاعون في مكانهم ، فبدأوا يهربوا من قريتهم عشان ميموتوش،\nفالحاكم دعا ربنا إنه يُوريهم آية إنهم مهما هربوا فمحدش فيهم هيقدر يهرب من الموت لو كان خلاص جاء أجله، \nفربنا استجاب لطلب الحاكم وقال لبني إسرائيل موتوا.. فماتوا قبل آجالهم النهائية المكتوبة..\nيعني لو مثلا كان المفروض إنهم يموتوا وهمّ عندهم ١٠٠ سنة، ربنا أماتهم بدري وهمّ عندهم ٦٠، يعني لسه فاضل لهم ٤٠ سنة، وبقول ده كمثال لتقريب المعنى \nفقعدوا ميتين بالمنظر ده 8 أيام، لحد ما بطونهم اتنفخت، وريحتهم بدأت تطلع...\nفحاول باقي القرية إنهم يدفنوهم معرفوش لإنهم كانوا بالآلاف..! فسابوهم..\nفمرّ عليهم نبي الله حِزقِيل فتعجب من منظرهم، فربنا قال له : أُرِيك آية؟\nقال حزقيل: نعم، فأحياهم ربنا كلهم من تاني، ورجعوا لقومهم وعاشوا معاهم لحد ما استكملوا آجالهم المكتوبة.\n☆طبعا القصة دي من كلام المفسرين، لأن القرآن والسنة متعرضوش للتفصيل ده،\nواحنا عارفين إن القرآن مش كتاب تاريخ عشان يحكي لنا القصة بالتفصيل، لكن ربنا بيقول لنا القصة من الزاوية إللي فيها العبرة المُستفادة منها\nوالرسالة أو العبرة إللي ربنا بيعلمهالنا من القصة دي هي إننا نتوكل عليه عز وجل، ومنحاولش نهرب من مُسببات الموت بترك الأمور الواجبة إللي ربنا أمرنا بيها وإللي ممكن لو عملناها نتعرض للموت،\nيعني مينفعش نقوم سايبين طاعة ربنا عشان خايفين من الموت، فربنا بيعلمنا إن ده حرام وغلط كبير وسوء تفكير وضعف إيمان\nيعني همّ عصوا أمر ربنا بالجهاد عشان خايفين من الموت \nوالهلاك إللي هو أصلا بيد الله،\nونسيوا إن لو ربنا شاء هياخد أرواحهم حالا حتى لو كانوا بس قاعدين على سرايرهم بدون أي قتال أو مرض أو سبب ظاهر للموت،\nفربنا بيعلمنا بقصتهم إن محدش يملك لك ضر ولا نفع إلا إذا ربنا أَذن\nلكن مش معنى كده إن الإنسان لا يحتاط ويقوم رايح يرمي نفسه في المهالك\nلأ طبعا.. ناخد بالأسباب إللي ندفع بيها سبب الهلاك أو الموت عشان ربنا أمرنا بده لإن حفظ النفس من الضرورات الخمس في مقاصد الشريعة، \nلاااااكن من غير ما يتسبب أخدنا للأسباب في معصيتنا لله وتركنا لطاعة من طاعاته عز وجل \nلأن حفظ الدين مُقَدَّم على باقي الضرورات الخمس\n☆الضرورات الخمس كلها هي:\n حفظ الدين، ثم حفظ النفس، ثم حفظ العِرض/النسل، ثم حفظ العقل، ثم حفظ المال.\nفلو تعارض حفظ الدين مع حفظ النفس يتم تقديم حفظ الدين مباشرةً؛ لإن هو ده إللي عشانه اتخلقنا وبالتالي في سبيله يهون كل شيء وربنا قال:\n \"وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ \".\nفلما يحصل موقف يكون الإختيار فيه بين مصلحة نفسي واتباع ديني...يبقى لازم اتبع ديني ولو على حساب مصلحتي، وربنا قادر إنه يعوضني بعدين لأن هو بإيده الملك كله والرزق كله\nوهو ده المغزى من إن ربنا يقول لنا قصة الناس إللي عصوا أمر الله بالجهاد عشان يحافظوا على حياتهم من الموت\nبعد موت حِزقيل عليه السلام، انتشر الفساد وانحرف الناس عن أوامر ربنا ، لدرجة إنهم عبدوا الأصنام\nفربنا أرسل لهم نبي تاني اسمه إِلياس بن ياسين، من نسل هارون عليه السلام،\n\"وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ..\" \nويُعرف في كتب الإسرائيلين باسم إيلِيا...لكن عندنا في القرآن إلياس،\nوكان الأنبياء في بني إسرائيل من بعد موسى عليه السلام بيجددوا إحياء شريعة موسى ويذَكّروا بيها الناس،\nفربنا أرسل النبي إلياس كرسول لبني إسرائيل إللي كانوا بيعبدوا صنم اسمه بَعْل،\n\"أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ\"\nفبدأ يدعوهم لعبادة الله الخالق الرازق... \n\"اللَّهَ رَبَّكُمْ وَرَبَّ آبَائِكُمُ الْأَوَّلِينَ\" ، \nونصحهم وذكَّرهم بقصص السابقين إللي ربنا أهلكهم، ولكنهم مستجابوش له \n فربنا توعَّدهم بعذاب يوم القيامة زي  ما قال في الآية: \"فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُون\".  \nووعد الناس إللي اتبعوا إلياس عليه السلام بالثواب يوم القيامة، \nومدح عز وجل إلياس عليه السلام وإنه لم يُقَصِّر في دعوته\nيعني ربنا لم يهلكهم في الدنيا ولم يعذبهم زي باقي الأمم السابقة..\n☆احنا حاسين إن القصة عادية صح\nلأ مش صح\nلإن زي ما قلنا، ربنا مش بيقول أي كلام عبث كده وخلاص حاشاه سبحانه، ولا بيحكي لنا قصص من باب تكرار كده وخلاص من غير ما يكون بيلفت نظرنا لعبرة في القصة\nوالعبرة في قصة إلياس هي إنه عليه السلام دعا قومه بكل الأساليب،\n بالترغيب والترهيب وبالحسنى زيه زي باقي الأنبياء السابقين، يعني ما قصرش في دعوته، \n طيب كانت إيه النتيجة ؟ ...النتيجة كانت إن قومه كذبوه، \n برغم كل إللي عمله،\nوهنا أول فائدة لنا وهي:\n♡إننا ممكن نكون بنستخدم كل أساليب الدعوة إلى الله وفعلا مش مقصرين ومع ذلك الناس تكذّبنا وتسخر مننا عادي جدا زي ما حصل مع إلياس عليه السلام \n \nطيب بقى هل لما كذبوه ربنا أهلكهم؟\nلأ لم يهلكهم ولكن توعدهم بعذاب الآخرة...ودي الفائدة التانية، وهي:\n♡ إن ربنا بيقولنا مش لازم تشوف هلاك الفاجر أو الكافر أو الفاسق أو الظالم في الدنيا، ممكن تلاقيه عايش حياته بيعمل ما بدا له وعنده أموال وأولاد ومنصب وكل النعم،\nلكن مش معنى كده إنه على حق...لأ ده هيشوف الويل في الآخرة\nحتى ربنا بيقول إيه:\n\"وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا أَنَّمَا نُمْلِي لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِي لَهُمْ لِيَزْدَادُوا إِثْمًا ۚ وَلَهُمْ عَذَابٌ مُّهِينٌ \"\nيعني الناس دي متفكرش إن ربنا سايبهم كده على كفرهم وظلمهم إن دي حاجة كويسة ليهم، لأ ده سايبهم عشان كل مايزدادوا في الطغيان كل ما عذابهم هيزيد\nوطبعا في المقابل المؤمنين إللي بيتعرضوا للظلم أجرهم هيزيد، \nفمش لازم تشوف هلاك الظالم بعينك..ممكن انت تموت وهو لسه عايش عادي جدا ،زي ما أبو جهل قتل سمية وزوجها ياسر ، همّ ماتوا واستمر أبو جهل عايش بعدهم،\nوربنا قال لرسول الله ﷺ في القرآن:\n\"فَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ\"\n وقال:\n\"وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ اللَّهُ شَهِيدٌ عَلَى مَا يَفْعَلُونَ\"\nفربنا بيأكد علينا في القرآن العبرة دي أكتر من مرة، عشان نتعلم إن احنا دورنا فقط هو التبليغ،\nأما عاقبة الناس فأمرهم بإيد ربنا وحده، يعذبهم في الدنيا بعصيانهم،\nأو يأجل عقابهم للآخرة، أو يتوب عليهم قبل الممات ويقبلهم مع الطائعين، ده مش مفروض يأثر فيك أو يلهيك عن مهمتك، فإنما علينا البلاغ وعلى ربنا الحساب\nالفائدة الثالثة هي:\n♡إننا نوصل دين ربنا وخلاص...سواء الناس استجابت ولّا لأ،\nاحنا مش مطلوب مننا إننا نُكره الناس ونغصبهم على تطبيق نصايحنا بالطاعة وترك المعاصي،\nولعل إجبارنا ليهم ده بالكلام أو بالفعل ده إللي بيخلي الناس أحيانا تَنفُر مننا بالفعل، لأنهم بيحسوا إننا عايزين نتحكم فيهم ونمشيهم على مزاجنا،\nفبيبان كإني عاوز الحق يوصلك عن طريقي أنا وبس.. \nواحنا نفسنا ساعات بنبقى فاهمين غلط،\nبنبقى فاهمين إننا لما نقول لحد أي نصيحة المفروض إنه ينفذها في نفس اللحظة في ساعتها،\nفلما ميعملش كده نقوم نتعصب وتقلب بخناق وحرقة دم\nونسينا إن رسول الله وهو رسول الله قعد ١٣ سنة في مكة يدعو الناس لقول لا إله إلا الله ولم يسلم إلا القليل\nوربنا قال لرسول الله ﷺ  نفسه: \n\"وَمَا جَعَلْنَاكَ عَلَيْهِمْ حَفِيظًا ۖ وَمَا أَنتَ عَلَيْهِم بِوَكِيلٍ\"\nوقال له في آية تانية إنه يقول ده للناس بوضوح كمان: \n\"قُلْ يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الْحَقُّ مِن رَّبِّكُمْ ۖ \nفَمَنِ اهْتَدَىٰ فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَا أَنَا عَلَيْكُم بِوَكِيلٍ \"\nيعني نبلغ دين ربنا ...والله الناس آمنوا واتبعوا؟ هياخدوا أجرهم في الآخرة..\nطب لم يتبعوا؟ خلاص دي حاجة ترجع لهم ولربهم ، همّ إللي هيتحاسبوا وهو اللي هيحاسبهم\nلكن مش معنى كده إني أسيب الناس من غير ما أمرهم بالمعروف وأنهاهم عن المنكر عشان ما استجابوش من أول مرة\nلأ طبعا احنا نأمر بالمعروف وننهى عن المنكر ونبلغ دين ربنا ليل نهار، لكن ننوع في الأسلوب مع المعاندين، مرة بالترغيب في الأجر،\nومرة بالترهيب من عذاب ربنا للي بيخالف أوامره ومرة بالكلمة، ومرة بالصحبة، ومرة بالنصيحة، ومرة بالهدية، ومرة بالقصة... وهكذا زي ما كان رسول الله ﷺ بيعمل مع الناس إللي بيدعوهم.\nبعد موت إلياس عليه السلام تولى النبوة ابن عمه 《اليسع》، وكان إلياس عليه السلام بيربيه عشان يتحمل أعباء النبوة من بعده.\nفسار اليسع على نفس منهج إلياس عليه السلام ، وكان بيدعو بني إسرائيل لعبادة الله والتمسك بشريعته سبحانه،\nظل فيهم مدة زمنية الله أعلم بيها ، لحد ما مات عليه السلام، مفيش عنه أخبار مُفَصّلة زي باقي الأنبياء..\nلكن بنو إسرائيل كَثُر فيهم الفساد والفجور والظلم، لدرجة إنهم بقوا يقتلوا الأنبياء\nوكان عندهم تابوت، صندوق يعني، فيه آثار من أغراض موسى عليه السلام،\nزي بعض ملابسه مثلا، وكانت العصا كمان موجودة في الصندوق ده، و بعض ألواح التوراة، \nفربنا سلط الجبابرة على بني إسرائيل وأخرجوهم من القدس وسرقوا التابوت، ورجعوا مشردين تااااني في الأرض\nهل سيظل بنو إسرائيل مشردين؟\nولا هيحاولوا يرجعوا لبيت المقدس مرة تانية؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆"}, {"n": 27, "l": "الجزء ٣٧ | طالوت وجالوت", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_السابعة_والثلاثون\n#قصة_طالوت_وجالوت\nوقفنا المرة إللي فاتت عند بني إسرائيل لما ربنا سلط عليهم الجبابرة أو العماليق وسرقوا منهم التابوت وأخرجوهم من القدس وشردوهم بسبب فجورهم وقتلهم لأنبيائهم،\nومات ملك بني إسرائيل في الوقت ده من الهم والحزن بسبب سرقة التابوت،\nفأصبح مفيش حاكم يجمعهم تحت راية واحدة، \nواحنا قلنا المرة إللي فاتت إن المُلك والنبوة انفصلوا عن بعض، يعني النبي بييجي من سِبط ، والمَلك أو الحاكم من سِبط تاني، والسّبط هنا معناه قبيلة،\nلكن المقصود بكلمة الأسباط هم الأنبياء من ذرية يعقوب عليه السلام.. عشان بس مايحصلش لخبطة\nمفيش مَلِك .. لكن النبوة موجودة... مستمرة .. لإن الدين لازم يُقام في جميع الأحوال\nبنو إسرائيل تعبوا وزهقوا من التشريد وعايزين يرجعوا للقدس، ويسترجعوا أبناءهم المأسورين عند الجبابرة،\nفراحوا لنبي ذلك الزمان،\nويُقال إن اسمه 《شَمُوِيل》 أو 《سَمْعُون》 طبعا مفيش دليل على الاسم ده، يعني اسمه عرفناه من الإسرائيليات، إللي لا بنصدقها ولا بنكذبها زي ما قلنا قبل كده،\nفقالوا له: إحنا عايزين مَلِك عشان يقودنا للجهاد في سبيل الله، فاختار لنا مَلِك\n\"أَلَمْ تَرَ إِلَى الْمَلَأِ مِنْ بَنِي إِسْرَائِيلَ مِنْ بَعْدِ مُوسَى إِذْ قَالُوا لِنَبِيٍّ لَهُمُ ابْعَثْ لَنَا مَلِكًا نُقَاتِلْ فِي سَبِيلِ اللَّهِ \"\nفنبيهم رد عليهم وقال لهم\nولما يتفرض عليكم الجهاد وبعدين متجاهدوش بقى\n\"قَالَ هَلْ عَسَيْتُمْ إِنْ كُتِبَ عَلَيْكُمُ الْقِتَالُ أَلَّا تُقَاتِلُوا \"\n☆ده احنا حفظناكم خلاص... كلام وشعارات وبس\nفردوا بكل حماس وقالوا:\nإزاي مش هنجاهد والعمالقة أخرجونا من بيوتنا وشردونا وأسروا أبنائنا\n\"قَالُوا وَمَا لَنَا أَلَّا نُقَاتِلَ فِي سَبِيلِ اللَّهِ وَقَدْ أُخْرِجْنَا مِنْ دِيَارِنَا وَأَبْنَائِنَا\"\nوكان عددهم حوالي ٨٠ ألف..فربنا فرض عليهم الجهاد زي ما طلبوا... والنتيجة متوقعة طبعا\nرجعوا في كلامهم ومجاهدوش، إلا القليل جدا منهم.. \n\"فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ تَوَلَّوْا إِلَّا قَلِيلًا مِنْهُمْ\"\n☆وده أول اختبار يسقطوا فيه مع النبي الجديد\n \n¤عارفين الموقف ده زي إيه\nلما مجموعة من الشباب أو البنات مثلا يسمعوا إن الإلتزم بدين ربنا ده حاجة جميلة، وإن نهاية الإلتزام ده الجنة، فيبدأوا يطلبوا إنهم يدخلوا بقى في الالتزام ده ويتعرفوا أكتر عليه،\nوبعدين بقى لما يبدأوا يعرفوا إن الواحد لازم يصلي الصلوات كلها في مواعيدها وبشروطها، وميفطرش في رمضان وميغتابش ولا يكذب ولا يحسد ولا يسخط وينفق من فلوسه زكاة المال،\nوإن في حجاب بشروط معينة وفي اجتناب للمحرمات وووإلخ... تلاقي جزء من الناس دي يقولوا إيه العقد والتشدد ده \nلا لا خلونا زي ماحنا، و أصلا ربنا غفور رحيم \nمش معقولة هيدخلنا النار عشان حبة شعر مش مغطيينهم، مش معقولة هيعذبنا عشان حبة حركات رياضية مانتظمناش فيها -إللي هي الصلاة-\nأنا هتصدق بدالها وده إللي أقدر عليه وربنا عارف إللي  في قلبي والإيمان إيمان القلب..\nوهنا الناس تبدأ تِفصل العمل عن الإيمان تماما، \nوده أكبر خطر ممكن الواحد يتعرض له، لإن الإيمان اعتقاد بالقلب وقول باللسان وعمل بالأركان.. والعمل دليل على الإيمان والطاعة.. لكن مين يفهم الكلام\nأهه بني إسرائيل لما شافوا إن الموضوع صعب عليهم تراجع الجزء الأكبر منهم،  والجزء الأقل هو إللي كمل الطريق\nنبيهم قال لهم:\nمش انتم طلبتم مَلك؟ ربنا جعل لكم طالوت مَلِك يحكمكم\n\"وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا\"\nفقالوا:\nإزاي يكون مَلك علينا واحنا أحق بالمُلك منه! المُلك في القبيلة بتاعتنا من زمان، إزاي واحد من قبيلة تانية هو إللي يكون ملك علينا\nوكمان معندوش فلوس كتير و مش من الأثرياء\n\" قَالُوا أَنَّى يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ \"\n☆وده تاني اختبار يسقطوا فيه مع النبي الجديد تاني\n¤يعني انتم أهم حاجة عندكم دلوقتي إن المُلك يبقى فيكم\nيعني يا إما احنا يا إما لأ\nهو إيه المهم بالنسبالكم دلوقتي؟ مش المهم إنكم ترجعوا بلدكم وتحرروا أبناءكم المأسورين، ولّا المهم الجاه والمنصب والرياسة والزعامة\nالمفروض إن المهم إن النصر يتحقق وتعيشوا في سلام في أرضكم، ومش مهم على إيد مين يتحقق الكلام ده، وخصوصا إن ربنا هو إللي اختار المَلِك ده،\nيعني مش مثلا النبي نفسه هو إللي اجتهد في اختياره ليكم فممكن مثلا يكون فيه نقاش، لأ، ده بيقول لكم بوضوح \n\"إن الله قد بعث لكم طالوت مَلِكا\"\nفنبيهم كرر عليهم إن ربنا هو إللي اختاره مش أنا،\nوالعبرة مش بكثرة المال ، في عطايا ومزايا تانية مهمة ربنا رزقه بيها، ربنا أعطاله علم وجسم ضخم، ودي كلها مميزات مش عندكم \nثم ربنا يُعطي الملك لمن يريد، هو يعلم تماما الشخص المناسب لكل مهمة\n\"قَالَ إِنَّ اللَّهَ اصْطَفَاهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ وَاللَّهُ يُؤْتِي مُلكَهُ من يَشَاء\"\n¤وهو ده معيار الاختيار للقادة إللي القرآن بيعلمهولنا، معيار القوة والعلم ، مش المال ولا الوجاهة ولا النسب والحسب، \nوبيعرف يتكلم بعلم مش زي غيره نقعد نعصر دماغنا عشان نفهم جملة مفيدة \nالمهم يعني مع إن طالوت كان قليل المال ومن قبيلة تانية غير قبيلة الملوك؛ لكن هو أحق بالملك بسبب مواصفات فيه مكنتش موجودة في حد غيره.\nفقالوا لنبيهم واحنا نعرف منين إن انت صادق وبتقول الحق وإن ده كلام ربنا؟!\nفرد عليهم وقال:\n علامة مُلكه إن التابوت إللي اتسرق منكم ، الملائكة هتحمله وهتجيبه لحد عندكم من تاني\n\"وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَنْ يَأْتِيَكُمُ التَّابُوتُ فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسَى وَآلُ هَارُونَ تَحْمِلُهُ الْمَلَائِكَةُ\"\nولقوا التابوت فعلا طاير في السماء لحد ما وصل عندهم،  وفتحوه ولقوا فيه أثار موسى عليه السلام، فقبلوا بملك طالوت على مضض وهمّ متأزمين نفسيا..هيعملوا إيه يعني مضطرين يوافقوا\nفطالوت بدأ يجهز الجيش إللي هيروح يقاتل بيه الجبابرة،\nطالوت عارف إن في الجيش بتاعه ناس معترضين عليه ومش عايزينه وهم دلوقتي داخلين معركة،\nفإزاي هيعتمد عليهم كده ويضمن ثباتهم عند مواطن الخطر الشديدة؟\nده ممكن في لحظة يتخلوا عنه ويعرضوا الكل للهلاك\nفكان لازم اختبار لهم قبل المعركة... \nلما مشي طالوت بالجنود فترة وهم في الطريق عطشوا، \nفقال لهم طالوت ربنا هيبتليكم ويختبركم عشان يشوف إذا كنتم هتقدروا تكملوا ولّا لأ ويعلم الصادق من الكاذب،\nاحنا هنعدي على نهر..فمحدش يشرب من النهر ده، \nإللي هيشرب منه مش هيكمل معايا... إلا لو بس شرب شربة ماء واحدة بإيده كده عشان يبل ريقه زي ما بنقول،\n\"فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِ قَالَ إِنَّ اللَّهَ مُبْتَلِيكُمْ بِنَهَرٍ فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنِّي وَمَنْ لَمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي إِلَّا مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ \"\nفلما وصلوا للنهر...كوووولهم شربوا منه إلا مجموعة قليلة جدا.\n\"فَشَرِبُوا مِنْهُ إِلَّا قَلِيلًا مِنْهُمْ \"\nعددهم ٣١٤  فقط، من أصل 80 ألف جندي، همّ فقط إللي نجحوا في الاختبار \n☆سهل أوي إني اقول إني مؤمن وإني مُناصر للحق وإني هدافع عن الدين و....و... وربنا يعلم الصادق في كلامه فعلا ويعلم المُدَّعي، \nلكن ربنا مش بيحاسبنا بسابق علمه فينا،\nلازم يكشفنا قصاد أنفسنا احنا صادقين فعلا ولّا لأ ، فبيبتلينا بالاختبارات الكاشفة.. ويا بخت إللي ربنا يبَصَّرَهُ بعيوب نفسه فيصلحها ويتوب عنها ويصبر عند الفتن\nالناس إللي خرجت مع طالوت للجهاد مقدروش يصبروا عن شوية مية،\nفإزاي هيصبروا على الموت أو الأسر أو الجرح في سبيل الله!؟\nإزاي هيثبتوا قدام مواجهة ناس بالقوة دي وهمّ ماقدروش يثبتوا قدام حبة مية زيادة عن قدر الحاجة فقط\n☆عارفين زي إيه\nزي لما أعلنت أمريكا إن القدس عاصمة الكيان الصهيوني، الشباب اتحمسوا بقى ويلّا افتحوا لنا باب الجهاد وعالقدس رايحين شهداء بالملايين،  \nوهمّ أصلا نفس الشباب دول ناشرين على صفحاتهم على فيسبوك أفلام وأغاني وصور نساء متبرجات وألفاظ نابية ونكت فيها شرك ومنكرات  وكلام عن الأبراج و...و... وماخفي كان أعظم \nطيب إنت أصلا مش قادر تقاوم شهوة نفسك في مساحة معركتك الشخصية الضيقة جدا اللي اسمها \"فيسبوك\"  هتعرف تثبت في أرض معركة وجهًا لوجه مع سيوف وقنابل؟!\nإنت بتقوم تصلي الفجر بالعافية في البرد، ده إذا قمت أصلا\nانت بتقوم من على موبايلك والألعاب والنت بالعافية مش قادر تقاوم شهوتك ومزاجك! وعايز تقاتل في سبيل الله؟ \nطب إزاي؟ \nفي حياة كل واحد فينا ابتلاء زي ابتلاء النهر كده، بمعاصي أو حتى إفراط في المباحات على حساب الأولويات،\nلكن على حسب إيمان وشخصية كل واحد فينا بيكون الوقوع الخطأ أو بيكون العصمة منه\nوفي النهاية ، لا يدخل الجنة إلا المؤمنون الصابرون،\n\"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَاهَدُوا مِنكُمْ وَيَعْلَمَ الصَّابِرِينَ\"\nبتجاهد نفسك وتصبر على الطاعة ولّا لأ؟\n◇بتصبر على كظم الغيظ، ولّا سايب بركان غضبك يفور وقت ما يحب؟ \n◇بتصبر على إجبار نفسك على اختيار الكلام الطيب وانت بتكلم الناس، ولّا بتخبط في وشهم الكلام إللي زي الطوب بدون أي مجهود في مراجعته وتحسينه؟\n◇بتصبر على الإحسان للناس برغم الإساءة، ولا بتسيب نار الثأر تاكل كل شيء لإن نفسك عندك مقدسة مينفعش حد يمسها بسوء وأسيبه يعيش حياته بعدها ببساطة؟\n◇بتصبر إنك تتبع منهج رسول الله ﷺ برغم مخالفة الناس حواليك لمعظم الدين دلوقتي، والا بتعوم على عومهم وخلاص بدون أي مقاومة؟\n◇بتجاهد نفسك وتصبر عن الغيبة، ولاّ ما بتقدرش تلجّم لسانك؟ فإزاي هتقدر تلجّم فرسك في الجهاد بقى؟ \nشوف ابتلاء النهر إللي في حياتك إيه هو وفتش عنه، وحاسب نفسك وابدأ عالجها.. قد أفلح من زكاها.. وقد خاب من دساها..\nالحياة لسه فيها فرص مفتوحة قصادنا، غيرنا بيتمنى إنه يرجع للفرص دي كلها... فسارعوا إلى مغفرة من ربكم\nنرجع لطالوت و نشوف كمل الطريق إزاي،\nطالوت أخد الـ٣١٤ مؤمن إللي صبروا معاه ، واتوجه بيهم ناحية بيت المقدس،\nلما وصلوا هناك وشافوا جيش الجبابرة الضخم  -وكان القائد بتاعهم اسمه جالوت وكان ضخم وقوي جدا- خافوا\nوقالوا احنا مش هنقدر على جالوت وجنوده .. عددنا بقى صغير أوي وهمّ أعدادهم كثيرة وأقوى مننا\n\"فَلَمَّا جَاوَزَهُ هُوَ وَالَّذِينَ آمَنُوا مَعَهُ قَالُوا لَا طَاقَةَ لَنَا الْيَوْمَ بِجَالُوتَ وَجُنُودِهِ\"\nفرد عليهم العلماء العالمون وقالوا:\nإن النصر مش بالكثرة ولا بالقوة ولا بالعتاد، لكن بالتقوى والصدق والإيمان الراسخ والتوكل على الله والاعتصام به،\nربنا هو إللي بينصر الفئة القليلة على الفئة الكثيرة، مادامت الفئة القليلة مؤمنة بالشكل ده\nقَالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلَاقُو اللَّهِ كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ\"\nدول الناس إللي على يقين من لقاء الله والآخرة، وده ردهم الطبيعي في كل زمان ومكان.\n لما اصطف الجيشين للقتال ، المؤمنين دعوا ربنا إنه يرزقهم الصبر ويثبت أقدامهم عشان يقدروا يكملوا المعركة وينتصروا فيها على جيش الكفار \nوَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِهِ قَالُوا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ\"\n☆وهنا في فائدة لينا...وهي إننا المطلوب مننا ناخد بالأسباب إللي نقدر عليها وخلاص،\nمالناش دعوة بالنتائج.. النتائج دي بتاعة ربنا\nوفي الأول وفي الآخر ربنا هو إللي بيوفّق ويعين، يعني مش بشطارتي إني أقوم لصلاة الفجر في عز البرد... مش بشطارتي إني ألتزم بدين ربنا في وسط مجتمع بيعمل كل إللي هو عايزه،\nإنما الأمور كلها بحول الله وقوته والاستعانة بيه عز وجل\nجالوت قائد الجبابرة طلب حد يبارزه من جيش طالوت، فخافوا ومحدش قام قصاده\nماعدا شاب كان عمره ساعتها ١٦-١٧ سنة كده، قال لطالوت : أنا هبارزه\nفطالوت قال له لو قتلت جالوت هزوجك بنتي وهخليك مَلِك من بعدي\n☆وده ينفع عادي من باب التشجيع، زي المكافآت إللي بتتعمل في مسابقات حفظة القرآن كده، من باب التشجيع أكتر على الطاعة\nفقام الشاب -وكان اسمه داوُد- وخرج لمبارزة جالوت ، فاستغرب جالوت إزاي شاب صغير جسمه ضئيل عايز يبارزني أنا\nمعندكوش حد أكبر وأضخم منه ولّا إيه\nدخل عليه داود.. وكان سلاحه \"المِقلاع\"، ودي أداة رَمْي، حاجة كده زي نبلة مثلا لكن بطريقة مختلفة ،\nعبارة عن جلدة بيحط فيها الحجارة مربوطة بحبل ويقعد يلف فيها ثم فجأة يحدفها على الهدف،\nلو بتشوفوا أطفال فلسطين وهمّ بيستعملوها في مقاومتهم لليهود، هتعرفوها\nفداود وضع تلاتة من الحجارة في الجلدة وقعد يلفها .. يلفها.. يلفها.. لحد ما فجأة رماها على جبهة جالوت فأصابه وقتله\n\"وَقَتَلَ دَاوُدُ جَالُوتَ\"..\nوقع جالوت ميت فالمؤمنين اتشجعوا يقاتلوا باقي الجيش ، وبالفعل انتصروا عليهم، \"فهزموهم بإذن الله\"\nواستعادوا القدس ورجعوا للبلد الكريمة تاني.\nوتزوج داود من ابنة طالوت وتولى المُلك من بعده زي ما وعده طالوت\nمين هو داود؟ وكيف كان حكمه في بني إسرائيل؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 28, "l": "الجزء ٣٨ | داود ١ | الجزء ٣٩ | داود ٢ ___ سليمان ١", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الثامنة_والثلاثون\n#قصة_داود_الجزء_الاول\n¤قبل ما أبتدى قصة النهاردة في ملحوظة مهمة عايز أقولها عشان إللي ميعرفش يعرف\nوهي إن أي معلومة بقولها عليها دليل من القرآن أو السنة أو كلام جمهور العلماء من المذاهب الأربعة ،أو جمهور المفسرين،\nمش بجيب أقوال شاذة، \nولو في أي إسرائيليات من إللي يجوز نحكيها كما قال رسول الله ﷺ... بنَبّه عليها لما بقولها،\n☆نرجع لقصتنا \nوقفنا المرة إللي فاتت عند داود لما قتل جالوت وكان طالوت وعد داود إنه يزوجه ابنته ويكون وريثه في الملك،\nونفّذ طالوت وعده وزوجه ابنته، وأحب بنو إسرائيل داود،\nمين بقى داود\nفاكرين لما اتكلمنا عن خلق آدم عليه السلام وإن ربنا مسح على ظهره وأراه ذريته، وكان كل واحد من أبناؤه كان في وجهه نور، ماعدا واحد بس كان النور ده شديد أوي، \nفجذب انتباه آدم عليه السلام، فسأل ربنا عنه فقال له الله إن هذا داود فأعطاه آدم من عمره أربعين سنة عشان يكمل عمره مائة عام؟\nأهه هو ده داود \nكان داود من نسل يعقوب عليه السلام...تولى حكم بني إسرائيل وأعطاه الله النبوة \nفكان أول نبي يجمع النبوة والملك بعد يوشع بن نون عليه السلام،\nفاكرين لما قلنا إن المُلك كان في سِبط والنبوة في سِبط، دلوقتي اجتمعت تاني في داود عليه السلام\n\"وشَدَدْنَا مُلْكَهُ وَآتَيْنَاهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ\"\nوربنا قال له إنه يحكم بين الناس بالعدل والحق ولا يتبع الهوى، يعني متحكمش لحد عشان هو قريبك أو صديقك ويكون الحق مش معاه،\nولا تحكم ضد عدوك بالظلم ويكون الحق معاه، وإلا هتكون من الضالين عن طريق الله وطريق الحق، وإللي بيضل عن الطريق هيكون من المعذبين عذاب شديد يوم القيامة لإنهم ما عملوش حساب وقفة يوم الجزاء\n\"يَا دَاوُودُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُمْ بَيْنَ النَّاسِ بِالْحَقِّ وَلَا تَتَّبِعِ الْهَوَى فَيُضِلَّكَ عَنْ سَبِيلِ اللَّهِ إِنَّ الَّذِينَ يَضِلُّونَ عَنْ سَبِيلِ اللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ بِمَا نَسُوا يَوْمَ الْحِسَابِ \"\n☆ربنا بيقول الكلام ده لداود النبي... فما بالنا بينا احنا\nعاش داود عليه السلام مع بني إسرائيل في القدس، وكان بيحكم بينهم بالعدل، ومع إنه كان ملك لكنه كان بيشتغل ، كان بيصنع دروع،\nعارفين دروع الحرب إللي كان بيلبسها الجنود زمان عشان تحميهم في الحروب \nأهه أول واحد اخترع الدروع دي كان داود عليه السلام بتعليم الله له.. وكان الموضوع سهل على داود عليه السلام، لإن ربنا أعطاه له آية أو معجزة، وهي معجزة لِين الحديد بين يديه، \nيعني لما كان يمسك الحديد كان يقدر يشكِّله ويتحكم فيه من غير ما يضطر الأول يسخنه جاااامد جدا عشان يبقى طري ويتمكن من تشكيله،\nيعني الحديد في إيده كان بيتشكل بسهولة زي العجينة الطرية إللي بنشكلها ونعمل منها مخبوزات\n \"وَأَلَنَّا لَه الْحَدِيدَ\"\nفكانت الدروع إللي بيعملها دقيقة جدا، خفيفة فمش بتعُوق الجنود في الجهاد، وفي نفس الوقت معمولة بإتقان يحميهم من ضربات العدو.\n\"وَعَلَّمْنَاهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّن بَأْسِكُمْ \"\n☆طيب وإيه المشكلة يعني لو ملبسوش دروع ؟\nما يموتوا وخلاص ومفيش داعي يحموا نفسهم من ضربات العدو...مش إللي بيموت في سبيل الله بيكون شهيد\n \nأيوة الشهادة في سبيل الله أقصى ما يتمنى الإنسان، لكن نتخيل كده لو كلنا متنا في سبيل مين إللي هينشر دين ربنا؟ مين إللي هيعلم الناس ويخرجهم من ظلمات الكفر؟ \nثم في المعارك لازم الأخذ بالأسباب إني أستمر على قيد الحياة أكبر وقت ممكن\nبحيث إني أزود عدد القتلى والخسائر إللي في صفوف العدو وأساعد جيش المسلمين بأكبر طاقة ممكنة، مش أدخل المعركة من غير أي عُدة ولا عتاد ولا دروع ولا خطط دفاعية، وأخلي الأعداء يقتلوني بحجة الشهادة\nده رسول الله ﷺ وهو رسول الله كان بيلبس الدروع وبيجهز الجيوش بالعتاد الكافي للقتال أطول فترة ممكنة لإجبار العدو على الانسحاب وإعلان هزيمته، \nوبيعمل الخطط الدفاعية المُحكمة\nفقبل الدخول في أي معركة لازم يكون الجنود مُجهّزين إيمانيًا، وكمان مُجهّزين على حسب استطاعتهم بالقوة والسلاح\nوربنا بيقول:\n\"وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ الْخَيْلِ \"\nداود عليه السلام برغم مُلكُه وشُغله في الحِدادة كان عابد لله، وكان بيصوم يوم ويفطر يوم، وده أفضل الصيام كما قال رسول الله ﷺ:\n\"إن أفضل الصيام صيام داود: كان يصوم يوماً ويفطر يوماً\"\nوربنا أنزل على داود عليه السلام الزَّبُور .. وكلمة الزبور نفسها معناها الكتاب، وكان الزبور عبارة عن حِكَم ومواعظ مكنش فيه حلال وحرام،\nعارفين كمثال: زي آيات الترغيب والترهيب في القرآن كده\nفكان داود يقرأها ويدندن بيها ويتغنّى في قراءتها ويحسّن بيها صوته وكان صوته جميل جدا مفيش لصوته مثال، بينضرب بيه المثل في الأصوات الجميلة.. يعني لو قلنا إن يوسف عليه السلام أخد جمال الشكل، فداود عليه السلام أخذ جمال الصوت \n☆وبالمناسبة داود عليه السلام مكنش بيستعمل المزمار زي ما الناس فاهمة، يعني رسول الله ﷺ  لما قال لأبي موسى الأشعري لما سمع تلاوته للقرآن:\n\" لقد أُوتيتَ مزمارًا من مزامير آل داود\" \nمكنش يقصد إن معاه مزمار موسيقي في بيته، لكن يقصد إن صوته حلو شبيه بصوت المزمار، فالموضوع مجرد تشبيه فقط\nكمان حديث عائشة رضي الله عنها لما دخل عليها أبوها أبو بكر الصديق رضي الله عنه، \nوكان فيه جاريتين صغيرتين بيغنوا في يوم الفطر أو يوم الأضحى وبيضربوا بالدف فقط، ورسول الله ﷺ موجود معاهم بس مديهم ضهره، فقال أبو بكر الصديق باستغراب واستنكار:\n《مزمار الشيطان في بيت رسول الله؟!》\nفرد رسول الله ﷺ وقال له إنه يسيبهم عادي لإن ده يوم عيد فعادي إنهم يغنوا، فكان المقصود هنا هو الغناء مع الضرب بالدف فقط،\n فالجاريتين الصغيرتين مكنش معاهم مزمار ولا حاجة؛\nلإن من المعروف في شريعة الإسلام إن أصوات الموسيقى محرمة، \nسواء كانت الموسيقى دي من آلات موسيقية معروفة أو أصوات بتخرج من الفم والحنجرة تشبه بالضبط صوت الموسيقى، \nزي الأكابيلا أو البِيت بوكس كده إللي منتشرين دلوقتي؛ لأن الأصل في التحريم على النتيجة مش على السبب\nعارفين زي تحريم الخمر كده\nأي حاجة بتؤدي للسُّكْر دخلت في التحريم، لأن في حاجات مستحدثة مكنتش موجودة على أيام رسول الله ﷺ ،\nفالحكم بيكون على النتيجة، يعني لو حاجة أدت لسُكر الإنسان دخلت في حكم الخمر، \nولو حاجة طلعت نفس صوت الموسيقى بالضبط دخلت في نفس حكم الموسيقى\nكان من جمال صوت داود عليه السلام ، إن الطيور والوحوش والجن والإنس بيتجمعوا حواليه يسمعوا تلاوته للزبور، ومبيتحركوش خااالص من شدة الاستماع بتركيز وإنصات وتأثر\nشوفوا كده لما بنسمع حد صوته حلو في القرآن مثلا ولاّ الأناشيد، بنكون عاملين إزاي\nأهه ده ما يجيش ذَرَّة في جمال صوت داود عليه السلام\nحتى إن الجبال والطيور كانت بتسبّح معاه لما تسمع صوته بالتسبيح،\n \"إنَّا سَخَّرْنَا الْجِبَالَ مَعَهُ يُسَبِّحْنَ بِالْعَشِيِّ وَالإِشْرَاقِ.. والطير محشورةً كل له أوَّاب..\"\nوكان عليه السلام مقسّم أيامه: \nيوم يتعبد فيه لله، ويوم يسمع فيه خصومة الناس ويحكم بينهم، ويوم لأشغاله ونسائه..\n☆وده يعلمنا إننا منسيبش نفسنا كده بدون تخطيط وزي ماتيجي تيجي\nلما نقسم وقتنا بين أمور الدنيا وأمور الآخرة هنرتاح جدا وهنعرف نركز وننجز بإذن الله، \nومش هنبقي متشتتين وفي دماغنا كذا حاجة ومش عارفين نكمل حاجة لآخرها وماشين في كذا اتجاه،\nوقتنا هو رأس مالنا، مينفعش نسيب نفسنا للسعي بدون خطط وترتيب أولويات وتقسيم للساعات وإعطاء كل ذي حق حقه، ولازم نحرص على إن ميبقاش في أوقات فراغ مهدورة بدون نية او عمل يعينا على الطاعة،\nفإياك والفراغ القاتل\n لإن النفس لو مشغلنهاش بالحق هتشغلنا هي بالباطل.. \nهي أكتر المعاصي سببها إيه؟ مش الفراغ\nلكن لو كل يوم بنصلي الصلوات المفروضة والسنن الرواتب، ولينا ورد من القرآن وبنسمع درس علم وبنقول أذكار اليوم والليلة وأذكار الأحوال وبنهتم بنفسنا وأهلنا والناس إللي حوالينا،\nوبنبلغ إللي اتعلمناه، وبنتابع أحوالنا بانتظام وتخطيط، سواء دراستنا أو بيوتنا أو أزواجنا أو أرحامنا أو أعمال البر والترويح عن النفس بالحلال للاستعانة على الطاعة وشحن الهمم...إلخ، بعد ده كله هنجيب وقت منين للفراغ ولا المعاصي\nودي أول حاجة نتعلمها من قصة داوود عليه السلام، تقسيم أوقاتنا كويس\n في يوم من الأيام إللي كان داود عليه السلام مخصصه للعبادة، في اتنين من الأشخاص تسلّقوا سور المكان إللي كان بيتعبد فيه، ودخلوا عليه فجأة،\nفاتخض وخاف زي أي بشر، وده من الخوف الفطري الطبيعي إللي مفيش حرج فيه، ولا ينتقص من عبودية الخوف من الله شيء،\nدي حاجة ودي حاجة.. \nيعني الخوف من الله فقط مقصود بيها إن لو حد هيعاقبني بشيء لو مسمعتش كلامه وكلامه ده فيه معصية لله عز وجل، أقوم أنا أسمع كلامه عشان خايف من عقابه ومخفش من عقاب ربنا على المعصية دي،\nيبقى أنا كده إيماني ناقص وفيه مشكلة لازم تتعالج\nلكن الخوف من الحاجات إللي فعلا تخوّف في الحياة بصفة عامة فده طبيعي ومفيهوش حرج شرعي..\nفداود خاف من إللي دخلوا عليه فجأة دول، فهو وإن كان نبي فهو بشر\n\"وَهَلْ أَتَاكَ نَبَأُ الْخَصْمِ إِذْ تَسَوَّرُوا الْمِحْرَابَ إِذْ دَخَلُوا عَلَى دَاوُودَ فَفَزِعَ مِنْهُمْ\"\nفطمنوه، وقالوا له ما تخافش مننا، إحنا مش جايين في شر أو ضرر ليك، ده إحنا الإثنين اختصمنا في شيء وجايين عشان عاوزينك تحكم بينا فيه بالعدل وتشوف الحق مع مين\n\"قَالُوا لَا تَخَفْ خَصْمَانِ بَغَى بَعْضُنَا عَلَى بَعْضٍ فَاحْكُمْ بَيْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ وَاهْدِنَا إِلَى سَوَاءِ الصِّرَاطِ\"\nوبدأ أول واحد فيهم يحكي المشكلة قال:\nده أخويا عنده تسعة وتسعين شاة، يعني عنده خير كثير من الأنعام يخليه قنوع وميبصش لغيره في رزقه.. وأنا عندي نعجة واحدة بس،\nفأخويا رغم غِناه ده كله قال لي أعطني النعجة بتاعتك دي، وغلبني في الكلام ومعرفتش أرد عليه\n\"إِنَّ هَذَا أَخِي لَهُ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِيَ نَعْجَةٌ وَاحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِي فِي الْخِطَابِ\"\nفقال داود عليه السلام :\n\"لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَى نِعَاجِهِ وَإِنَّ كَثِيرًا مِنَ الْخُلَطَاءِ لَيَبْغِي بَعْضُهُمْ عَلَى بَعْضٍ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَقَلِيلٌ مَا هُمْ\"\nيعني داود  عليه السلام حكم للي اتكلم ده، من غير ما يسمع لأخوه، إللي هو الطرف التاني من الخصومة او المشكلة،\nوكان حكمه إن الأخ التاني ده هو إللي ظالم لما طلب منك الشاة الواحدة إللي معاك في حين إن هو عنده تسع وتسعين نعجة غيرها،\nوقال له للأسف كتير من الشركاء والأخلّاء بيبغِي بعضهم على بعض، إلا طبعا إللي عنده من الإيمان بالله والعمل الصالح ما يمنعه من الظلم.. وما أقلهم\nوبعدين انتبه داود عليه السلام لكلامه وتيّقن إن ده كان اختبار من ربنا عز وجل في الحكم بين الناس بضوابط القضاء العادل،\nولكنه عليه السلام اتسرّع واتعجل في الحكم لما أشفق على الطرف إللي بيحكي، فاستغفر ربنا وسجد لله وتاب عن ده، \n\"وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ\"\nواحنا قلنا قبل كده إن الانبياء معصومين من الكفر والشرك والكبائر و الصغائر التي تدل على الخسة والدناءة،\nلكنهم غير معصومين من الخطأ العادي زي ما حصل مع يونس عليه السلام.. وزي ما حصل مع داود عليه السلام هنا \n☆طيب وهو فين الخطأ إللي وقع فيه داود عليه السلام\n◇أولا: \nإنه استمع لخصم واحد فقط ومسمعش من الطرف التاني في الخصومة مع إنه واقف قصاده كمان، فكان مفروض زي ما سمع من الأول كان لازم يسمع من التاني قبل ما يحكم أي حكم.. مش يمكن التاني هو إللي معاه الحق\n◇ثانيا:\nإنه حكم للشخص الأول بظاهر الأمور من غير ما يعرف هل  كلامه حقيقي فعلا وصدق ولّا مزود كلام من عنده؟ \nمش يمكن القصة محصلتش بالشكل ده؟ مش يمكن ناقصة حتة مهمة جدا تخليه ظالم مش مظلوم؟\n☆فاحنا لازم ناخد بالنا لما يجيلنا أي شخص عايز مشورة  وبيشتكي من حد تاني، متتبرعش مباشرة بدعم موقفه وتسخن على صاحبه وإنت أصلا ماسمعتش من الطرف التاني،\nوممكن إللي بيحكيلك يكون هو إللي غلطان أصلا وهو سبب الكارثة\nولو تفتكروا في قصة يوسف عليه السلام،\nإخوة يوسف جاءوا أباهم يبكون... أي حد معدي ما يعرفهمش كان هيتعاطف معاهم، في حين إن همّ إللي كانوا مجرمين أصلا مش مجرد مظلومين حتى\nويا سلام لو أخت بتحكي عن مشكلة بينها وبين زوجها في الجروبات \nتلاقي كل واحدة تقولها وإيه إللي يصبرك على زوج بالاخلاق دي؟!.. اطلقي منه طبعا... فدي مش معصية واحدة هنا، ده ذنب مُرَكَّب من كذا معصية لا يتسع المقام لتحليلها، \nوالسبب في الجرأة دي بيكون دايما إن الناس ناسيين \n\"ما يلفظ من قول إلا لديه رقيب عتيد\".. \n\"مَنْ يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُنْ لَهُ نَصِيبٌ مِنْهَا وَمَنْ يَشْفَعْ شَفَاعَةً سَيِّئَةً يَكُنْ لَهُ كِفْلٌ مِنْهَا \".\nثم حتى لو سمعت من الطرفين واتضح إن الكلام متطابق وفيه ظالم ومظلوم، ما تسخنش حد على حد، \nإنت دورك هنا تفض نزاع بالعدل أيوة، لكن ليك دور تاني إنك تؤلف بين القلوب وتلطف الجو بين الطرفين\n فلما داود عليه السلام إللي هو نبي، وقع في الخطأ ده وهو الحكم من غير ما يسمع من الطرفين تاب واستغفر، فما بالكم بينا إحنا \nواحنا ممكن نكون بنقع في الخطأ ده كتير واحنا مش حاسين\nفلما تاب داوود عليه السلام واستغفر، تاب الله عليه وأثنى عليه \n\"فَغَفَرْنَا لَهُ ذَلِكَ وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى وَحُسْنَ مَآبٍ\"\n☆وده يعلمنا طبعا إننا لما نذنب نسارع بالتوبة والاستغفار و الاعتذار لله عز وجل،\n \"وَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ\"\nفالتوبة لازم تكون فورية على طول بدون تأجيل وتسويف مهما اتكرر الذنب ده، وربنا بيغفر وبيرحم إللي بيتوب إليه يستغفره \n¤في هنا ملحوظة مهمة جداااااا\nوهي إن في قصة مشهورة عن داود عليه السلام لا تصح أبداااا وهي من الإسرائيليات المردودة إللي مش مقبولة،\nوالقصة دي بتقول: \nإن داود عليه السلام كان مُتزوج من تسعة وتسعين امرأة ، وشاف امرأة تانية غيرهم فعجبته،\nوكانت المرأة دي  متزوجة حد تاني، فأمر زوجها إنه يروح يقاتل في الحرب وإنه يكون في الصفوف الأولى في المعركة، عشان يموت فيتزوجها داود عليه السلام بعد منه ويكمل بيها عدد زوجاته 100،\nفربنا أرسل له في المحراب ملكين في صورة الخصمين دول ، عشان يعرَّفه خطأه بالقصة بتاعتهم دي إللي شبه قصته مع المرأة، وقالوا كلام كله قَدْح في داود عليه السلام،\nفالقصة بتاعة الزواج دي كلها \nلا تصح إطلاااقا يا جماعة\nوغير مقبولة حتى في حق رجل صالح من الصالحين العاديين، فما بالنا بنبي من الأنبياء المُصطَفين الأخيار\nداود عليه السلام كان عنده أبناء كتير، وكان عنده ابن مميَّز .. كان اسمه سليمان، \nكان سليمان بيساعد داود عليه السلام في أمور الحُكم وحل المشاكل والخصومات إللي بين بني إسرائيل.\nمن الأحداث إللي حصلت إن امرأتين اختصمتا إلى داود عليه السلام،\n يعني جم قاصدينه في حل مشكلة بينهم، وكان معاهم طفل رضيع كانت المرأة الكبيرة ماسكاه في إيدها،\nفالكبيرة دي قالت إن الطفل الرضيع ده ابنها، والصغيرة قالت لأ ده ابني أنا ، والذئب أكَل ابن أختي الكبيرة دي،\nفداود عليه السلام حَكَم للكبيرة، إما على أساس الشَبه إللي بينها وبين الطفل، أو على أساس إنه كان معاها هي في إيدها شايلاه؛ لإن مكنش فيه قدامه دليل أقوى من ده يقدر يحسم بيه القضية\n \nفلما خرجت المرأتين من عند داود عليه السلام، كان سليمان عليه السلام موجود،\nفعرضت الصغيرة القصة مرة ثانية عليه، \nفقال هاتوا السكين أقطعه بينكم وكل واحدة تاخد نص ليها، فصرخت الصغيرة وقالت لأ هو ابنها خلاص متئذيهوش\nفحكم سليمان عليه السلام بالطفل الرضيع للصغيرة؛\nلأنه عارف شفقة الأم وعارف إن أمه ممكن تتحمل فراقه بعيد عنها لكن ما تتحملش إنه يتعرض لألم أو قتل قدام عنيها ويكون بسببها كمان،\nفالأم يهمها إن ابنها يكون حي على قيد الحياة سليم ومعافَى، حتى لو مش في حضنها، بس ما يموتش أو يتأذي،\nفسليمان احتال حيلة مشروعة ، وهي إنه أوهمها إنه هيقطع الطفل عشان تُظهر المشاعر الحقيقية العفوية بعيد عن التمثيل\n☆ومن الحِيل المُشابهة إللي استعملها القضاة برده ، إن رجلين  اختصموا عند قاضي، فالمظلوم قال للقاضي:\nأنا أقرضت الراجل ده فلوس وهو مش راضي يرجعهالي، وبيقول ما أخدتش منك حاجة\nفالقاضي قال له: هل معاك شاهد؟.. فالمظلوم قال لأ،\nفالقاضي سأل: طب هل في أي علامة معينة؟\nفالمظلوم قال: أقرضته الأموال عند شجرة كذا...\nفالقاضي قال له:\nطيب روح عند الشجرة واستنى هناك.. وخلّى الراجل التاني يستنى معاه في  مجلس القضاء..\nفبدأ القاضي يقضي بين الناس ، والراجل التاني قاعد جنبه، وبعد شوية قليلة سأله القاضي فجأة:\nتفتكر صاحبك يكون وصل للشجرة\n .. فالراجل قال له:\n لأ.. مايلحقش لأنها بعيدة\nفالقاضي قال له: باااس تعال بقى ..عرفت منين مكان الشجرة وانت بتنكر أصلا الموضوع كله وإنك تعرف الشجرة\nفمبقاش قصاده غير إنه يعترف \nو دي من الحِيل المشروعة إللي ممكن نستعملها لو هتؤدي لاسترجاع الحق الحق من المنكرين\nطب إيه المواقف التانية إللي حصلت برده مع سليمان .....؟\n من المواقف إللي حصلت برده مع سليمان .....\nكفاية كده النهاردة نكمل الجزء الجاي إن شاء الله\n........\n#قصص_الأنبياء\n#الحلقة_التاسعة_والثلاثين\n#قصة_داود_الجزء_الثاني\n#قصة_سليمان_الجزء_الأول\nاتكلمنا المرة إللي فاتت عن داود عليه السلام وعرفنا إنه أول نبي يجمع بين النبوة والملك في بني إسرائيل،\nوداود عليه السلام كان أول نبي من بني إسرائيل يحكم معظم أرض فلسطين حكم إيماني لمدة أربعين سنة\n☆إيه ده، هل معنى كده إن أرض فلسطين والقدس بتاعة اليهود زي ما بيقولوا\nطبعا لأ مش بتاعتهم إطلاقا \nلإن القدس وفلسطين وبلاد الشام بصفة عامة فُتحت في عهد عمر بن الخطاب رضي الله عنه وبقت تحت حكم المسلمين،\nوأي دولة تُفتح وتُحكم بحكم الإسلام خلاص بقت بتاعة المسلمين ولو مر الزمن وتم احتلالها بيبقى واجب على المسلمين استرجاعها \nزي القدس في الوقت الحالي وزي أسبانيا والبرتغال برده، إللي كان بيُطلق عليها اسم بلاد الأندلس وهي:\n《الفردوس المفقود》\nمن الأحداث إللي حصلت في حياة داود عليه السلام\nقصة رواها ابن عباس رضي الله عنه إن رجلين اتنين  اختصموا عند داود عليه السلام، \nالأول قال إن الرجل التاني أخد البقر بتاعه بالغصب، لكن الرجل الثاني أنكر الموضوع... فأجّل داود عليه السلام الحكم في الموضوع بتاعهم لوقت الليل، فربنا أوحى له إنه يقتل الرجل المُدّعِي\nفتاني يوم داود عليه السلام قال للرجل الأول - إللي هو 《المُدَّعِي》- قولي حقيقة الموضوع .. ربنا أوحى لي إني أقتلك \nفالرجل قال: والله يا نبي الله أنا صادق في كلامي والرجل ده فعلا أخد البقر بتاعي غصبا\nلكن أنا قتلت أبوه من غير ماحد يعرف \n.. فأمر داود علي السلام إن الراجل يُقتل قَصاصًا \nومن الأحداث إللي حصلت برده وكان لسليمان الابن المتميز لداود عليه السلام دور فيه،\nرجلين جاءوا اختصموا عند داود عليه السلام، واحد عنده أغنام والثاني عنده أرض زراعية،\nفكان لما ييجي الليل⛼ كان صاحب الغنم يدخل غنمه الحظيرة.. ففي ليلة من الليالي الغنم\n طلعت من الحظيرة وراحت الأرض الزراعية بتاعة الرجل الثاني وقعدت تاكل منها وأفسدتها، \nربنا قال عنها في القرآن:\n\"وَدَاوُودَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَاهِدِينَ\"\nوطبعا صاحب الغنم مسؤول عن أغنامه في الليل إنه لازم ياخد باله منها ويقفل عليها كويس ويتأكد إنها مش مطلوقة على حد،\nبعكس بالنهار ليس عليه أي حرج لما الغنم يخرج للرعي ويدخل أرض زراعية بالغلط، لأن ساعتها بيبقى في أكثر من طريقة لمنعها...\nلكن في الليل الكل نايم فمين إللي هيمنعها غير راعيها\n فالإشكالية إن الغنم أفسدت الأرض في الليل،\nفلما راح الراجل صاحب الأرض لداود عليه السلام يشتكي، فحكم له داود عليه السلام إنه ياخد الغنم بتاعة الرجل وتبقى بتاعته،\nفسليمان بن داود عليه السلام قال إنه عنده رأي ثاني وهو:\nإن الرجل صاحب الغنم ياخد الأرض الزراعية يصلّحها، \nولما ترجع زي ماكانت يرجّعها لصاحبها، وإن الراجل صاحب الأرض الزراعية ياخد الغنم يستفيد منها لحد ما أرضه تتصلح وترجعله،\nفوافق الرجلين على حل سليمان ورضيوا به أكتر من الحل بتاع داود عليه السلام\n.. \n\"فَفَهَّمْنَاهَا سُلَيْمَانَ ۚ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا\"\n☆طيب هل معنى كده بقى إن سليمان أعلم من داود\nلأ..ربنا أعطى داود وسليمان العلم، لكن مش كل إنسان عنده علم لازم يكون عالم بكل المسائل، \nوربنا قال عن داود عليه السلام :\n\"وآتيناه الحِكمة وفصلَ الخطاب\"\nفعادي جدا لما تَخفَى عليه بعض المسائل ويكون فيها حل أحكم من حله أو أرجح منه \nفمش شرط إن الإنسان يفهم كل قضية جزئية عشان نقول إنه فاهم\nيعني لو عالم أصاب مثلا في ألف مسألة وأخطأ في مسألة معينة ... فمنقولش إنه لم يفهم، \nزي ما حصل في موقف الغنم ده بين داود وسليمان وموقف المرأتين من الجزء إللي فات، \nوساعات الإنسان بيحتاج مع العلم سرعة البديهة وحسن التصرف زي المواقف إللي حكم فيها سليمان\n◇وزي قصة حرامي الإِوَز \n والقصة هي إن في رجل راح اشتكى لإمام المسجد إن الإِوَز بتاعه بيتسرق من جيرانه لكنه مش عارف مين هو بالضبط،\nفبعد الصلاة قال للناس:\nإن جار فلان بيسرق الإِوَز بتاعه وبيدخل المسجد وهو على راسه ريش الوز، فواحد من إللي قاعدين مسح على راسه، فعرف إن هو إللي بيسرق الإوز\n¤وممكن العكس كمان... يعني يكون واحد عنده أصل العلم لكنه عنده بلادة أو غباء أو ضيق أُفق في الفهم والتطبيق\nزي الخوارج مثلا لما بيقولوا الآيات على غير معناها الصحيح،\nمثال: \nرسول الله ﷺ بيقول : \"شفاعتي لأهل الكبائر من أمتي\"\nفييجي واحد منهم يقول أهل الكبائر المقصود بيها هنا :أهل الصلاة والزكاة\nوبيستشهدوا بكلام ربنا: \" واستعينوا بالصبر والصلاة وإنها لكبيرة\"\nفبيقولوا إن المقصود بالكبائر في الحديث هو كبائر الطاعات،\nوالأصل والمتواتر إن لفظ الكبائر بتُطلق على المعاصي والذنوب\nأهه دول ناس عندهم العلم لكن مفيش أي ذرة فَهم\n◇ملحوظة مهمة عن الحديث عشان الناس متفهمش غلط\n \nمش معنى إن في شفاعة إن الإنسان يفتح على نفسه في باب الكبائر والمعاصي\nزي ما ربنا غفور رحيم فهو برده شديد العقاب عز وجل، وزي ما رسول الله ﷺ هيشفع لأهل الكبائر ،\nفكذلك سيُحجَب عنه ناس من أمته على الحوض وهيقول لهم سُحقًا لمن بدّل بعدي وغيّر في الدين، فخدوا بالكم\nعاش داود عليه السلام مائة عام، وحكم بني إسرائيل أربعين سنة، وكان شديد الغيرة على نسائه،\nفكان لما يخرج بيقفل كل الأبواب لا حد يدخل ولا حد يخرج ، لحد ما يرجع.. \nففي يوم خرج والأبوب اتقفلت كالعادة، فشافت زوجة من زوجاته رجل في وسط البيت فاتعجبت جدا وقالت: \nدخل منين ده، ودخل وسط البيت إزاي والأبواب مقفولة\n   جاء داود عليه السلام والرجل لسه قائم في وسط الدار زي ماهو، فداود سأله إنت مين؟\nفالراجل قال له: أنا إللي مبخافش من الملوك، ومفيش حد يقدر يمنع نفسه عني\nفعرفه داود عليه السلام وقال له: انت ملك الموت، فأهلا بأمر الله ...\nفقبض ملك الموت روحه في نفس مكانه.. بس كده\nفي لحظة معينة ربنا مقدرها ومكتوبة في اللوح المحفوظ حياة داود عليه السلام انتهت\n \nورحّب بملك الموت، وطبيعي إنه يرحب بيه، لإنه إنسان عاش طائع..عادل.. مؤمن، شديد التقوى لله عز وجل، أواب وكثير العبادة،\nفإزاي ميفرحش بالموت وهو البوابة إللي هيعدي منها للجنة ولقاء الله\n☆نسأل نفسنا لو ملك الموت جاء دلوقتي يقبض أرواحنا ، هل هنرحب بيه ،ولّا هنقول استنى بس أروح أمسح مقاطع الأغاني وصوري الوحشة وصور المنكرات إللي أنا ناشرها على شبكات التواصل،\nوأَلحق أرجع للناس فلوسها إللي عليّ وأظبط حجابي وأطلب العفو من إللي أنا آذيتهم؟!\nهل هرحب بيه، ولا هقوله استنى أمسح أرقام صُحبة السوء من على تليفوني وأروح اقرأ قرآن واستغفر وأتوب وأعمل الصالحات و...و...\nأنا شخصيا شوفت منشور على الفيس لبنت بتتكلم فيه عن كمية المسلسلات التركية إللي اتفرجت عليها والأفلام الأجنبية...\nوبعدها بأيام بسيطة ماتت، فجأة كده بدون مقدمات \nتعتقدوا لو كانت تعرف إنها هتموت خلال أيام كانت نشرت الكلام ده\nولّا كانت على الأقل هتنشر كلام يكون صدقة جارية ليها؟\nهي معملتش ... إحنا نعمل.. في الوقت إللي إحنا مكسلين فيه عن قول سبحان الله وبحمده أو قول استغفر الله،\nفي ملاييين تحت الأرض نفسهم يرجعوا عشان يقولوا الكلمتين دول... والسعيد من وُعِظَ بغيره\nأسأل الله العظيم رب العرش العظيم أن يرحمها و يتجاوز عنها ويغفر لها وأموات المسلمين أجمعين\nبعد موت داود عليه السلام ورثه ابنه المميز سليمان \n\"وَوَرِثَ سُلَيْمَانُ دَاوُودَ \"\nوالورث هنا مش وِرث أموال لكن وِرث العلم والنبوة،\nلإن إللي الأنبياء بيتركوه خلفهم من أموال بيكون مصيره الصدقة، ولا يَرِث الأقارب منهم أبدا زي باقي البشر،\n وسليمان عليه السلام وكل أنبياء بني إسرائيل على شريعة موسى عليه السلام حتى يأتي عيسى عليه السلام،\nوكان سليمان عليه السلام ذكي زي ما شفنا من المواقف بتاعته، \nوربنا أنعم عليه بنعم كثيرة منها القوة وسرعة البديهة، ومنها إنه علمه لغة الطيور... يعني لما يسمع صوت الطيور يفهم هم بيتكلموا عن إيه\n\"وَقَالَ يَا أَيُّهَا النَّاسُ عُلِّمْنَا مَنطِقَ الطَّيْرِ وَأُوتِينَا مِن كُلِّ شَيْءٍ إِنَّ هَذَا لَهُوَ الْفَضْلُ الْمُبِينُ\"\nومن القصص إللي يرويها ابن كثير عن فهم سليمان عليه السلام لكلام الطير،\nإنه عدّى على عصفور\n عمال يلف حوالين عصفورة\n، فقال لأصحابه: عارفين بيقولها إيه\nفقالوا : بيقول إيه\nقال سليمان عليه السلام: \nبيخطبها لنفسه وبيقول لو اتجوزتيني سأُسْكنك في أي غرف دمشق انتِ عايزاها، \nلأن غرف دمشق مبنية من الصخر، مش أي حد يقدر يسكنها،\nولكن كل خاطب كذاب\n☆سبحان الله زي عندنا بالضبط\nقبل الخطوبة والزواج تلاقيهم عاملين البحر طحينة وبعد الزواج مفيش لا بحر ولا طحينة\nإلا من رحم الله طبعا\nكان سليمان عليه السلام عنده زوجات كتير برده، ففي يوم من الأيام قال:\n\"لَأَطُوفَنَّ اللَّيْلَةَ علَى سَبْعِينَ امْرَأَةً، تَحْمِلُ كُلُّ امْرَأَةٍ فَارِسًا يُجَاهِدُ في سَبيلِ اللَّهِ، فَقالَ له صَاحِبُهُ:\nإنْ شَاءَ اللَّهُ، فَلَمْ يَقُلْ، ولَمْ تَحْمِلْ شيئًا إلَّا واحِدًا، سَاقِطًا أَحَدُ شِقَّيْهِ، فَقالَ النبيُّ ﷺ: لو قالَهَا لَجَاهَدُوا في سَبيلِ اللَّهِ.\nيعني هو قال إنه هيدخل على مائة امرأة كل واحدة منهن ستحمل منه ولد، ولما يتولدوا ويكبروا هيكونوا كلهم فرسان يقاتلوا في سبيل الله،\nفصاحبه قال له قل إن شاء الله لكنه نسي ولم يقل إن شاء الله،\nفمفيش ولا واحدة فيهم أنجبت، إلا واحدة بس ولدت نصف إنسان، يعني إنسان غير مكتمل\nولو كان قال إن شاء الله كان ربنا رزقه فعلا بمائة فارس يقاتل في سبيل الله،\nقال تعالى:\n\"وَلَقَدْ فَتَنَّا سُلَيْمَانَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِ جَسَدًا ثُمَّ أَنَابَ\"\nفالمقصود بالجسد هنا هو المولود إللي جاءت به القَابِلة لسليمان وهو على كرسيه عشان يشوفه، والقابلة يعني الدّاية إللي بتولّد،\nفكانت الفتنة والاختبار في المولود ده، يعني حصلت له خيبة أمل في إللي كان ناوي يعمله بإنه يخلّف مائة أو تسعين ولد كلهم يقاتلوا في سبيل الله، \nلكن ده محصلش لأنه مقلش إن شاء الله\nفمع إن الغاية بتاعته نبيلة وهدفه من الأبناء هو الجهاد في سبيل الله؛ لكن سنن ربنا مش بتحابي حد، إلا ما شاء الله، وربنا هنا أراد إنه يعلم سيدنا سليمان درس مهم ويعملنا من بعده إن تقديم المشيئة دايما قبل أي عمل هو من أعظم أسباب التوفيق فيه بإذن الله وحوله وقوته، ومن أهم صفات العبودية\n☆حتى مع رسول الله ﷺ ، لما المشركين سألوه عن أصحاب الكهف وعن الروح وعن ذي القرنين، فقال لهم هقول لكم بكرة ولم يقل إن شاء الله، فتأخر الوحي خمسة عشر يوم وبعدها نزلت سورة الكهف تجاوب على الأسئلة، \nوفيها الآية:\n\"ولا تقولنَّ لشيء إني فاعلٌ ذلك غدًا إلا أن يشاء الله، واذكر ربك إذا نسيتَ وقل عسى أن يهديني ربّي لأقرب من هذا رَشَدًا \".\n◇وهنعرف قصة أصحاب الكهف و ذو القرنين بعدين إن شاء الله.\nلما سليمان عليه السلام شاف إن إللي كان عايزه محصلش حاسب نفسه وراجعها وعرف خطأه وتاب واستغفر، \nوده يعلمنا لما دعوتنا متتحققش نراجع نفسنا يمكن في أمر بنعمله أو عملنا حاجة من موانع الإجابة، فيمكن محتاجين توبة واستغفار تبصّرنا بعيوبنا وتخلينا نتفادى ده في المستقبل\n◇ملحوظة مهمة\nالتفسير إللي أنا قلته عن آية :\n\"وَلَقَدْ فَتَنَّا سُلَيْمَانَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِ جَسَدًا ثُمَّ أَنَابَ\"\n هو أصح تفسير وهو إللي عليه الدليل من حديث رسول الله ﷺ إللي أنا قلته فوق\nلأن في تفاسير تانية بتقول إن الشيطان تشكل في هيئة سليمان عليه السلام وأخذ ملكه وحصلت أحداث كتيرة وكل الأحداث دي من الإسرائيليات إللي مش بناخد بيها لأنها تقدح في الأنبياء وتخالف الدليل،\nوالموضوع فيه تفصيل كبير بين العلماء، ممكن ترجعوا له في موقع الإسلام سؤال وجواب،\nالمهم،\nبعد ما سليمان عليه السلام  تاب واستغفر، طلب من ربنا طلب عجيب جدا\nقال: يارب اوهبني مُلك محدش شاف زيه ولا أخد مثيله غيري،لا قبلي ولا بعدي ... مُلك يكون ليّ أنا بس\n\"قَالَ رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَّا يَنبَغِي لِأَحَدٍ مِّن بَعْدِي ۖ إِنَّكَ أَنتَ الْوَهَّابُ\"\n☆إيه ده \nهو إزاي سليمان عليه السلام يطلب مُلك الدنيا والمعروف إن الناس المتعلقة بالدنيا هي إللي بتطلب مُلك الدنيا\nثم ليه يعني يقول إن محدش بعده ياخد نفس مُلكه، هيضره في إيه لو حد تاني ربنا آتاه مُلك زي بتاعه\n◇أولا:\nهو طلب مُلك الدنيا ساعتها عشان كان عايز يعرف منزلته عند ربنا لما يعطيه إللي هو طلبه منه، وإنه قبل توبته\nعارفين زي إيه \nزي لما بيكون مثلا نفسنا في حاجة من ربنا إنه يعملها لنا، الواحد مثلا نفسه يسافر ولّا يتزوج، ومن شدة الشوق لتحقق الرجاء نقوم نقول يارب لو انت هتحققهالي إديني علامة معينة.. \nوممكن عشان نتأكد أكثر كمان، احنا إللي نحدد العلامة دي بنفسنا وممكن تكون علامة مستحيلة تتحقق أصلا،  زي مثلا بنت تقول: يارب إللي هتزوجه ييجي يخبط عالباب دلوقتي\nأو شاب يقول: يارب العربية إللي عاوزها تكون من نصيبي أكسبها في مسابقة الكاراتيه مثلا.. بتحصل ساعات.. هي أه مستحيلة شوية، لكن بندعي بيها واحنا مستنيين على أمل وشوق هل ياترى ربنا هيحقق لنا العلامة دي ولّا لأ\n.\nهو ده كان نفس موقف سليمان عليه السلام تقريبا والله أعلم.\nإنما مكنش أبدا يريد الدنيا لأجل الدنيا\n◇ثانيا :\n لما قال إن محدش تاني يحصل على الملك ده: كان المقصود إن المُلك إللي هتديهولي يكون بتاعي محدش يقدر ياخده مني،\nومفيش حد من أهل زماني يكون عنده زيه، فيكون المُلك ده معجزتي وعلامة نبوتي بين الناس، ويكون حاجة خاصة بيّ تخصني بها عن سائر البشر\nفربنا استجاب له ورزقه بجيش مش زي أي جيش\nمفيش حد على الأرض إلى قيام الساعة هيمتلك مُلك ولا جيش زي جيش سليمان عليه السلام\nليه بقى؟\nلإن كان عنده جيش من الجن وجيش من البشر وجيش من الطير، وربنا علمه لغات كل المخلوقات دي.\n\"وَحُشِرَ لِسُلَيْمَانَ جُنُودُهُ مِنَ الْجِنِّ وَالإِنسِ وَالطَّيْرِ فَهُمْ يُوزَعُونَ\"\nفكان بيخرج للجهاد لنشر الإسلام لأنه كان ملك للأرض ونبي، فكان لازم يعلم الناس التوحيد\nففي مرة وهو راجع مع جيوشه، سمع صوت بيقول:\nيا جماعة خدوا بالكم أحسن سليمان وجنوده يقتلوكم وهم مش واخدين بالهم\nمين إللي اتكلم ده وقال الكلام ده \n \nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆☆"}]);
